  // 按价格升序排列商城各分类，确保新增物品自然插入对应价位区间
  [SHOP_PUP_OUTFITS, SHOP_PUP_ACCS, SHOP_PUP_COMPANIONS, SHOP_PUP_BADGES, SHOP_PUP_BAG_SKINS, SHOP_PUP_TRAILS, SHOP_PUP_BUBBLES, SHOP_PUP_AVATAR_FRAMES].forEach(arr => {
    if (Array.isArray(arr)) arr.sort((a, b) => (a.price || 0) - (b.price || 0));
  });
  if (Array.isArray(SHOP_PUP_GOODS)) {
    SHOP_PUP_GOODS.sort((a, b) => ((a.cat === 'gear' ? 0 : 1) - (b.cat === 'gear' ? 0 : 1)) || ((a.price || 0) - (b.price || 0)));
  }

