  // ==================== IndexedDB 本地大字体存储 ====================
  const openFontDB = () => new Promise((resolve, reject) => {
    if (!win.indexedDB) {
      reject(new Error('IndexedDB unavailable'));
      return;
    }
    const req = win.indexedDB.open(FONT_DB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(FONT_STORE_NAME)) {
        db.createObjectStore(FONT_STORE_NAME, { keyPath: 'id' });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });

  const dbPutFont = async (id, blob) => {
    const db = await openFontDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(FONT_STORE_NAME, 'readwrite');
      tx.objectStore(FONT_STORE_NAME).put({ id, blob });
      tx.oncomplete = () => { db.close(); resolve(); };
      tx.onerror = () => { db.close(); reject(tx.error); };
    });
  };

  const dbGetFont = async (id) => {
    const db = await openFontDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(FONT_STORE_NAME, 'readonly');
      const req = tx.objectStore(FONT_STORE_NAME).get(id);
      req.onsuccess = () => { db.close(); resolve(req.result?.blob || null); };
      req.onerror = () => { db.close(); reject(req.error); };
    });
  };

  const dbDeleteFont = async (id) => {
    const db = await openFontDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(FONT_STORE_NAME, 'readwrite');
      tx.objectStore(FONT_STORE_NAME).delete(id);
      tx.oncomplete = () => { db.close(); resolve(); };
      tx.onerror = () => { db.close(); reject(tx.error); };
    });
  };

  // ==================== IndexedDB 本地小说存储 ====================
  const openNovelDB = () => new Promise((resolve, reject) => {
    if (!win.indexedDB) { reject(new Error('IndexedDB unavailable')); return; }
    const req = win.indexedDB.open(NOVEL_DB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(NOVEL_STORE_NAME)) {
        db.createObjectStore(NOVEL_STORE_NAME, { keyPath: 'id' });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });

  const dbPutNovel = async (id, text) => {
    const db = await openNovelDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(NOVEL_STORE_NAME, 'readwrite');
      tx.objectStore(NOVEL_STORE_NAME).put({ id, text });
      tx.oncomplete = () => { db.close(); resolve(); };
      tx.onerror = () => { db.close(); reject(tx.error); };
    });
  };

  const dbGetNovel = async (id) => {
    const db = await openNovelDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(NOVEL_STORE_NAME, 'readonly');
      const req = tx.objectStore(NOVEL_STORE_NAME).get(id);
      req.onsuccess = () => { db.close(); resolve(req.result?.text || ''); };
      req.onerror = () => { db.close(); reject(req.error); };
    });
  };

  const dbDeleteNovel = async (id) => {
    const db = await openNovelDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(NOVEL_STORE_NAME, 'readwrite');
      tx.objectStore(NOVEL_STORE_NAME).delete(id);
      tx.oncomplete = () => { db.close(); resolve(); };
      tx.onerror = () => { db.close(); reject(tx.error); };
    });
  };

