  const sysNightBtn = root.querySelector('#st-tb-sys-night-btn');
  const sysDarkMql = typeof win.matchMedia === 'function' ? win.matchMedia('(prefers-color-scheme: dark)') : null;
  const parseCssColorRgb = (raw) => {
    if (!raw || typeof raw !== 'string') return null;
    const s = raw.trim();
    if (!s || s === 'transparent') return null;
    let m = s.match(/^rgba?\(\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)(?:\s*,\s*(\d+(?:\.\d+)?))?\s*\)$/i);
    if (m) {
      const a = m[4] === undefined ? 1 : parseFloat(m[4]);
      if (a <= 0.05) return null;
      return [parseFloat(m[1]), parseFloat(m[2]), parseFloat(m[3])];
    }
    m = s.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
    if (m) {
      const h = m[1];
      if (h.length === 3) return [parseInt(h[0]+h[0],16), parseInt(h[1]+h[1],16), parseInt(h[2]+h[2],16)];
      return [parseInt(h.slice(0,2),16), parseInt(h.slice(2,4),16), parseInt(h.slice(4,6),16)];
    }
    return null;
  };
  const resolveProbeColorRgb = (cssVal) => {
    try {
      const direct = parseCssColorRgb(cssVal);
      if (direct) return direct;
      const probe = doc.createElement('span');
      probe.style.cssText = 'position:fixed;left:-9999px;top:-9999px;visibility:hidden;pointer-events:none;';
      probe.style.color = cssVal;
      doc.body.appendChild(probe);
      const comp = win.getComputedStyle(probe).color;
      probe.remove();
      return parseCssColorRgb(comp);
    } catch (_) { return null; }
  };
  const syncSystemNightMode = () => {
    const enabled = Boolean(config.followSystemNight);
    const isDark = Boolean(sysDarkMql && sysDarkMql.matches);
    if (enabled && isDark) {
      root.dataset.sysNight = '1';
      if (config.theme === 'auto') {
        const rootStyle = win.getComputedStyle(doc.documentElement);
        const stBgRaw = rootStyle.getPropertyValue('--SmartThemeBlurTintColor').trim() || win.getComputedStyle(doc.body).backgroundColor;
        const bgRgb = resolveProbeColorRgb(stBgRaw);
        const bgLum = bgRgb ? (0.299 * bgRgb[0] + 0.587 * bgRgb[1] + 0.114 * bgRgb[2]) : 255;
        if (bgLum > 135) {
          root.dataset.autoNight = '1';
        } else {
          delete root.dataset.autoNight;
        }
      } else {
        delete root.dataset.autoNight;
      }
    } else {
      delete root.dataset.sysNight;
      delete root.dataset.autoNight;
    }
    if (sysNightBtn) {
      sysNightBtn.classList.toggle('active', enabled);
      sysNightBtn.textContent = enabled ? (isDark ? '跟随日夜：夜' : '跟随日夜：日') : '跟随日夜：关';
    }
  };
