  const visitorCanvas = root.querySelector('#st-tb-visitor-canvas');
  const visitorBubbleEl = root.querySelector('#st-tb-visitor-bubble');
  const persHeadEl = root.querySelector('#st-px-pers-head');
  const potionCntEl = root.querySelector('#st-px-potion-cnt');
  const persBoxEl = root.querySelector('#st-px-pers-box');
  const dataExportBtn = root.querySelector('#st-tb-data-export');
  const dataImportBtn = root.querySelector('#st-tb-data-import');
  const dataFileInput = root.querySelector('#st-tb-data-file');
