  const bagPalPanelEl = root.querySelector('#st-tb-bag-pal-panel');
  if (furToggleBtn && furPanelEl) {
    furToggleBtn.addEventListener('click', () => {
      const open = furPanelEl.style.display === 'none';
      furPanelEl.style.display = open ? 'block' : 'none';
      furToggleBtn.textContent = open ? '收起' : '展开';
    });
  }
  if (bagPalToggleBtn && bagPalPanelEl) {
    bagPalToggleBtn.addEventListener('click', () => {
      const open = bagPalPanelEl.style.display === 'none';
      bagPalPanelEl.style.display = open ? 'block' : 'none';
      bagPalToggleBtn.textContent = open ? '收起' : '展开';
    });
  }
  const pupSpeedRange = root.querySelector('#st-tb-pup-speed');
  const pupSpeedVal = root.querySelector('#st-tb-pup-speed-val');
  const pupOpacityRange = root.querySelector('#st-tb-pup-opacity');
  const pupOpacityVal = root.querySelector('#st-tb-pup-opacity-val');
  const pxBarHunger = root.querySelector('#st-px-bar-hunger');
  const pxNumHunger = root.querySelector('#st-px-num-hunger');
  const pxBarThirst = root.querySelector('#st-px-bar-thirst');
  const pxNumThirst = root.querySelector('#st-px-num-thirst');
  const pxBarMood = root.querySelector('#st-px-bar-mood');
  const pxNumMood = root.querySelector('#st-px-num-mood');
  const pxNumCoins = root.querySelector('#st-px-num-coins');

  const getContext = () => win.SillyTavern?.getContext?.() || null;
  const clamp = (val, min, max) => Math.max(min, Math.min(max, val));
  const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
  const randInt = (min, max) => min + Math.floor(Math.random() * (max - min + 1));

  const shadeHex = (hex, factor = 0.88) => {
    const clean = String(hex || '#fffdf7').replace('#', '');
    if (clean.length !== 6) return '#efe1cc';
    const r = clamp(Math.round(parseInt(clean.slice(0, 2), 16) * factor), 0, 255);
    const g = clamp(Math.round(parseInt(clean.slice(2, 4), 16) * factor), 0, 255);
    const b = clamp(Math.round(parseInt(clean.slice(4, 6), 16) * factor), 0, 255);
    return `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`;
  };

  // ==================== 自定义字体（IndexedDB 本地大字体 + URL 链接） ====================
  const renderFontSelect = () => {
    fontSelect.innerHTML = '';
    const defOpt = doc.createElement('option');
    defOpt.value = '';
    defOpt.textContent = '默认（跟随酒馆）';
    fontSelect.appendChild(defOpt);

    config.fontRecipes.forEach((f) => {
      const opt = doc.createElement('option');
      opt.value = f.id;
      const tag = f.type === 'local' ? '[本地]' : '[链接]';
      opt.textContent = `${tag} ${f.name}`;
      fontSelect.appendChild(opt);
    });

    const exists = config.fontRecipes.some(f => f.id === config.activeFontId);
    if (!exists) config.activeFontId = '';
    fontSelect.value = config.activeFontId;
    fontDelBtn.disabled = !config.activeFontId;
    fontDelBtn.style.opacity = config.activeFontId ? '1' : '0.45';
  };

  const applyCustomFont = async () => {
    if (activeFontBlobUrl) {
      win.URL.revokeObjectURL(activeFontBlobUrl);
      activeFontBlobUrl = null;
    }
    if (fontLinkEl) {
      fontLinkEl.remove();
      fontLinkEl = null;
    }
    fontStyleEl.textContent = '';

    if (!config.activeFontId) {
      fontStatusEl.textContent = '';
      return;
    }

    const recipe = config.fontRecipes.find(f => f.id === config.activeFontId);
    if (!recipe) return;

    const applyFamilyRule = (familyName) => {
      fontStyleEl.textContent += `\n#chat .mes_text, #chat .mes_text p, #chat .mes_block { font-family: "${familyName}", -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif !important; }`;
    };

    if (recipe.type === 'local') {
      fontStatusEl.textContent = '加载中...';
      try {
        const blob = await dbGetFont(recipe.id);
        if (!blob) {
          fontStatusEl.textContent = '本地文件丢失';
          return;
        }
        activeFontBlobUrl = win.URL.createObjectURL(blob);
        const fam = `ST_TB_Font_${recipe.id.replace(/[^a-zA-Z0-9]/g, '')}`;
        fontStyleEl.textContent = `@font-face { font-family: "${fam}"; src: url("${activeFontBlobUrl}"); font-display: swap; }`;
        applyFamilyRule(fam);
        fontStatusEl.textContent = '已应用';
      } catch (_) {
        fontStatusEl.textContent = '读取失败';
      }
      return;
    }

    const url = String(recipe.url || '').trim();
    if (!url) return;
    const isCssLink = /\.css(\?|$)/i.test(url) || /fonts\.googleapis\.com/i.test(url) || /zeoseven/i.test(url);

    if (isCssLink) {
      fontLinkEl = doc.createElement('link');
      fontLinkEl.rel = 'stylesheet';
      fontLinkEl.href = url;
      doc.head.appendChild(fontLinkEl);

      let fam = String(recipe.family || '').trim();
      if (!fam) {
        const m = url.match(/family=([^:&]+)/i);
        if (m) fam = decodeURIComponent(m[1]).replace(/\+/g, ' ');
      }
      if (!fam) {
        try {
          const res = await win.fetch(url);
          if (res.ok) {
            const cssText = await res.text();
            const fm = cssText.match(/font-family\s*:\s*['"]?([^'";}]+)/i);
            if (fm) fam = fm[1].trim();
          }
        } catch (_) {}
      }
      if (fam) {
        applyFamilyRule(fam);
        fontStatusEl.textContent = '已应用';
      } else {
        fontStatusEl.textContent = '已加载CSS（可填族名）';
      }
    } else {
      const fam = `ST_TB_UrlFont_${recipe.id.replace(/[^a-zA-Z0-9]/g, '')}`;
      fontStyleEl.textContent = `@font-face { font-family: "${fam}"; src: url("${url}"); font-display: swap; }`;
      applyFamilyRule(fam);
      fontStatusEl.textContent = '已应用';
    }
  };

  // ==================== 阅读微调（含首行缩进 + 0贴边对称） & 沉浸模式 ====================
  const parsePositiveDecimal = (val) => {
    const s = String(val ?? '').trim();
    if (!s) return null;
    const n = parseFloat(s);
    return Number.isFinite(n) && n >= 0 ? n : null;
  };

  const applyReadingStyle = () => {
    const fs = parsePositiveDecimal(config.fontSize);
    const lh = parsePositiveDecimal(config.lineHeight);
    const pg = parsePositiveDecimal(config.paraGap);
    const sp = parsePositiveDecimal(config.sidePadding);

    const textRules = [];
    if (fs !== null && fs > 0) textRules.push(`font-size: ${fs}px !important;`);
    if (lh !== null && lh > 0) textRules.push(`line-height: ${lh} !important;`);

    const parts = [];
    if (textRules.length) {
      parts.push(`#chat .mes_text, #chat .mes_text p { ${textRules.join(' ')} }`);
    }
    if (pg !== null) {
      parts.push(`#chat .mes_text p { margin-bottom: ${pg}px !important; } #chat .mes_text p:last-child { margin-bottom: 0 !important; }`);
    }
    if (config.textIndent) {
      parts.push(`#chat .mes_text p { text-indent: 2em !important; }`);
    }
    if (sp !== null) {
      parts.push(`
        :root { --card-pad-x: ${sp}px !important; }
        #sheld { padding-left: 0 !important; padding-right: 0 !important; }
        #chat { padding-left: 0 !important; padding-right: 0 !important; }
        #chat .mes {
          padding-left: ${sp}px !important;
          padding-right: ${sp}px !important;
          margin-left: 0 !important;
          margin-right: 0 !important;
          box-sizing: border-box !important;
        }
        #chat .mes_block {
          padding-left: 0 !important;
          padding-right: 0 !important;
          margin-left: 0 !important;
          margin-right: 0 !important;
          box-sizing: border-box !important;
        }
        #chat .mes_text {
          padding-left: 0 !important;
          padding-right: 0 !important;
          margin-left: 0 !important;
          margin-right: 0 !important;
          box-sizing: border-box !important;
        }
      `);
    }
    readStyleEl.textContent = parts.join('\n');
  };

  const applyImmersive = () => {
    doc.documentElement.classList.toggle('st-tb-immersive', Boolean(config.immersive));
  };

  // ==================== 双模式后台保活（强效 5分钟+ 防截断 + 切回自动补拉同步） ====================
  let kaAudioEl = null;
  let kaAudioUrl = null;
  let kaAudioCtx = null;
  let kaOsc = null;
  let kaWorker = null;
  let kaWorkerUrl = null;
  let kaWakeLock = null;
  let kaLockRelease = null;
  let kaNeedsGesture = false;
  let kaHiddenAt = 0;

  const createSilentWavUrl = () => {
    const sampleRate = 8000;
    const numSamples = sampleRate * 2; // 2 秒静音 PCM
    const buffer = new ArrayBuffer(44 + numSamples * 2);
    const view = new DataView(buffer);
    const writeStr = (off, str) => {
      for (let i = 0; i < str.length; i++) view.setUint8(off + i, str.charCodeAt(i));
    };
    writeStr(0, 'RIFF');
    view.setUint32(4, 36 + numSamples * 2, true);
    writeStr(8, 'WAVE');
    writeStr(12, 'fmt ');
    view.setUint32(16, 16, true);
    view.setUint16(20, 1, true);
    view.setUint16(22, 1, true);
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * 2, true);
    view.setUint16(32, 2, true);
    view.setUint16(34, 16, true);
    writeStr(36, 'data');
    view.setUint32(40, numSamples * 2, true);
    const blob = new Blob([buffer], { type: 'audio/wav' });
    return win.URL.createObjectURL(blob);
  };

  const acquireWebLock = () => {
    if (kaLockRelease || !win.navigator?.locks?.request) return;
    try {
      win.navigator.locks.request('st_tb_keepalive_lock', () => new Promise((resolve) => {
        kaLockRelease = resolve;
      })).catch(() => {});
    } catch (_) {}
  };

  const releaseWebLock = () => {
    if (typeof kaLockRelease === 'function') {
      try { kaLockRelease(); } catch (_) {}
      kaLockRelease = null;
    }
  };

  const requestKaWakeLock = async () => {
    try {
      if (win.navigator?.wakeLock?.request && !doc.hidden) {
        if (kaWakeLock) {
          try { await kaWakeLock.release(); } catch (_) {}
          kaWakeLock = null;
        }
        kaWakeLock = await win.navigator.wakeLock.request('screen');
      }
    } catch (_) {}
  };

  let kaNoticeTimer = null;
  const showKaPolicyNotice = (msg) => {
    let el = doc.getElementById('st-tb-ka-notice');
    if (!el) {
      el = doc.createElement('div');
      el.id = 'st-tb-ka-notice';
      el.style.cssText = 'position:fixed;left:50%;top:18px;transform:translateX(-50%);max-width:min(320px,calc(100vw - 28px));padding:8px 13px;border-radius:10px;background:var(--tb-bg,#fff);color:var(--tb-text,#222);border:1px solid var(--tb-border,#ddd);box-shadow:0 6px 20px rgba(0,0,0,0.18);font-size:11.5px;line-height:1.5;z-index:10035;pointer-events:none;opacity:0;transition:opacity 0.2s ease;text-align:center;';
      root.appendChild(el);
    }
    el.textContent = msg;
    el.style.opacity = '1';
    clearTimeout(kaNoticeTimer);
    kaNoticeTimer = setTimeout(() => { el.style.opacity = '0'; }, 3200);
  };

  const kaRuntime = {
    active: false,
    mode: 'mix',
    startedAt: 0,
    lastBeatAt: 0,
    recoverCount: 0,
    interrupted: false,
  };

  const updateKeepAliveUI = () => {
    if (!keepAliveBtn) return;
    const curPolicy = config.keepAlivePolicy === 'exclusive' ? 'exclusive' : 'mix';
    if (config.keepAlive) {
      keepAliveBtn.textContent = kaNeedsGesture ? '后台保活：待轻点' : '后台保活：开';
      keepAliveBtn.classList.add('primary');
      if (keepAliveTip) {
        keepAliveTip.style.display = 'block';
        keepAliveTip.innerHTML = `<div style="display:flex;align-items:center;gap:5px;">` +
          `<button type="button" class="st-tb-mini-btn${curPolicy === 'mix' ? ' active' : ''}" data-kapolicy="mix" style="flex:1;" title="不占系统音频栏，可与语音视频共存">轻保活</button>` +
          `<button type="button" class="st-tb-mini-btn${curPolicy === 'exclusive' ? ' active' : ''}" data-kapolicy="exclusive" style="flex:1;" title="占用系统音频栏，适合长时间息屏常驻">强保活</button>` +
          `</div>${kaNeedsGesture ? '<div style="margin-top:4px;font-size:10.5px;color:var(--tb-sub);">轻点页面任意位置完成激活</div>' : ''}`;
        keepAliveTip.querySelectorAll('[data-kapolicy]').forEach(btn => {
          btn.addEventListener('click', (e) => {
            e.stopPropagation();
            const pol = btn.dataset.kapolicy;
            if (pol !== 'mix' && pol !== 'exclusive') return;
            if (config.keepAlivePolicy === pol && kaRuntime.active) return;
            config.keepAlivePolicy = pol;
            saveConfig();
            startKeepAlive();
            showKaPolicyNotice(pol === 'exclusive'
              ? '已切换为强保活：会占用系统音频栏，长时间息屏更稳，遇到其他软件发声时可能暂时让出通道'
              : '已切换为轻保活：不占系统音频栏，可与微信语音、视频和游戏共存');
          });
        });
      }
    } else {
      keepAliveBtn.textContent = '后台保活：关';
      keepAliveBtn.classList.remove('primary');
      if (keepAliveTip) {
        keepAliveTip.style.display = 'none';
        keepAliveTip.textContent = '';
      }
    }
  };

  const stopKeepAlive = () => {
    kaNeedsGesture = false;
    releaseWebLock();
    if (kaAudioEl) {
      try { kaAudioEl.pause(); } catch (_) {}
      kaAudioEl.removeAttribute('src');
      kaAudioEl.remove();
      kaAudioEl = null;
    }
    if (kaAudioUrl) {
      win.URL.revokeObjectURL(kaAudioUrl);
      kaAudioUrl = null;
    }
    if (kaOsc) {
      try { kaOsc.stop(); } catch (_) {}
      kaOsc = null;
    }
    if (kaAudioCtx) {
      try { kaAudioCtx.close(); } catch (_) {}
      kaAudioCtx = null;
    }
    if (kaWorker) {
      try { kaWorker.terminate(); } catch (_) {}
      kaWorker = null;
    }
    if (kaWorkerUrl) {
      win.URL.revokeObjectURL(kaWorkerUrl);
      kaWorkerUrl = null;
    }
    if (kaWakeLock) {
      try { kaWakeLock.release(); } catch (_) {}
      kaWakeLock = null;
    }
    if (typeof win.__stKaCleanRecovery === 'function') {
      try { win.__stKaCleanRecovery(); } catch (_) {}
      win.__stKaCleanRecovery = null;
    }
    kaRuntime.active = false;
    kaRuntime.interrupted = false;
    if (!config.keepAlive) {
      kaRuntime.startedAt = 0;
      kaRuntime.lastBeatAt = 0;
      kaRuntime.recoverCount = 0;
    }
    updateKeepAliveUI();
  };

  const startKeepAlive = async () => {
    stopKeepAlive();
    if (!config.keepAlive) return;
    const mode = 'strong';
    acquireWebLock();

    const kaPolicy = config.keepAlivePolicy === 'exclusive' ? 'exclusive' : 'mix';
    kaRuntime.active = true;
    kaRuntime.mode = kaPolicy;
    if (!kaRuntime.startedAt) kaRuntime.startedAt = Date.now();
    kaRuntime.lastBeatAt = Date.now();
    kaRuntime.interrupted = false;

    try {
      if (win.navigator && win.navigator.audioSession) {
        win.navigator.audioSession.type = kaPolicy === 'mix' ? 'ambient' : 'playback';
      }
    } catch (_) {}

    const tryResumeKaAudio = (fromInterruption = false) => {
      if (!config.keepAlive) return;
      kaRuntime.lastBeatAt = Date.now();
      if (kaAudioEl) {
        if (kaAudioEl.error || kaAudioEl.ended) {
          try {
            if (kaAudioUrl) { kaAudioEl.src = kaAudioUrl; kaAudioEl.load(); }
          } catch (_) {}
        }
        if (kaAudioEl.paused) {
          kaAudioEl.play().then(() => {
            kaRuntime.interrupted = false;
            if (fromInterruption) kaRuntime.recoverCount += 1;
            if (kaNeedsGesture) { kaNeedsGesture = false; updateKeepAliveUI(); }
          }).catch(() => {});
        }
      }
      if (kaAudioCtx && kaAudioCtx.state === 'suspended') {
        kaAudioCtx.resume().then(() => {
          kaRuntime.interrupted = false;
          if (fromInterruption) kaRuntime.recoverCount += 1;
          if (kaNeedsGesture) { kaNeedsGesture = false; updateKeepAliveUI(); }
        }).catch(() => {});
      }
    };
    const kaKeepInterval = setInterval(() => tryResumeKaAudio(true), 2000);
    const onKaWakeEvt = () => { if (!doc.hidden) tryResumeKaAudio(true); };
    const onKaTapWake = () => tryResumeKaAudio(false);
    doc.addEventListener('visibilitychange', onKaWakeEvt);
    win.addEventListener('focus', onKaWakeEvt);
    win.addEventListener('pageshow', onKaWakeEvt);
    doc.addEventListener('pointerdown', onKaTapWake, true);
    doc.addEventListener('touchstart', onKaTapWake, { capture: true, passive: true });
    win.__stKaCleanRecovery = () => {
      clearInterval(kaKeepInterval);
      doc.removeEventListener('visibilitychange', onKaWakeEvt);
      win.removeEventListener('focus', onKaWakeEvt);
      win.removeEventListener('pageshow', onKaWakeEvt);
      doc.removeEventListener('pointerdown', onKaTapWake, true);
      doc.removeEventListener('touchstart', onKaTapWake, true);
    };

    let kaBeatN = 0;
    if (typeof win.Worker === 'function') {
      try {
        const wBlob = new Blob([
          'let t=setInterval(()=>{postMessage(Date.now());},1000);onmessage=()=>{clearInterval(t);};'
        ], { type: 'application/javascript' });
        kaWorkerUrl = win.URL.createObjectURL(wBlob);
        kaWorker = new win.Worker(kaWorkerUrl);
        kaWorker.onmessage = () => {
          if (!config.keepAlive) return;
          kaBeatN += 1;
          kaRuntime.lastBeatAt = Date.now();
          tryResumeKaAudio(true);
          if (doc.hidden && kaBeatN % 8 === 0) {
            try { win.fetch('/csrf-token', { cache: 'no-store' }).catch(() => {}); } catch (_) {}
          }
        };
      } catch (_) {}
    }

    if (kaPolicy === 'mix') {
      // 混音策略：静音 PCM 缓冲循环叠加混音通道，不占顶部音频栏，方便同时听发语音与刷视频
      const AC_Mix = win.AudioContext || win.webkitAudioContext;
      if (AC_Mix) {
        try {
          kaAudioCtx = new AC_Mix();
          const silentBuf = kaAudioCtx.createBuffer(1, 22050, 22050);
          const srcNode = kaAudioCtx.createBufferSource();
          srcNode.buffer = silentBuf;
          srcNode.loop = true;
          const gainNode = kaAudioCtx.createGain();
          gainNode.gain.value = 0.0001;
          srcNode.connect(gainNode);
          gainNode.connect(kaAudioCtx.destination);
          srcNode.start(0);
          kaOsc = srcNode;
          kaAudioCtx.onstatechange = () => {
            if (config.keepAlive && kaAudioCtx && kaAudioCtx.state === 'suspended') {
              kaRuntime.interrupted = true;
              setTimeout(() => tryResumeKaAudio(true), 300);
            }
          };
          if (kaAudioCtx.state === 'suspended') kaAudioCtx.resume().catch(() => {});
        } catch (_) {}
      }
    }

    if (mode === 'strong') {
      kaAudioUrl = createSilentWavUrl();
      kaAudioEl = doc.createElement('audio');
      kaAudioEl.src = kaAudioUrl;
      kaAudioEl.loop = true;
      kaAudioEl.volume = kaPolicy === 'mix' ? 0.0001 : 0.001;
      kaAudioEl.setAttribute('playsinline', '');
      kaAudioEl.setAttribute('webkit-playsinline', '');
      kaAudioEl.style.display = 'none';
      const onKaInterrupted = () => {
        if (!config.keepAlive) return;
        kaRuntime.interrupted = true;
        setTimeout(() => tryResumeKaAudio(true), 300);
        setTimeout(() => tryResumeKaAudio(true), 1200);
        setTimeout(() => tryResumeKaAudio(true), 2800);
      };
      kaAudioEl.addEventListener('pause', onKaInterrupted);
      kaAudioEl.addEventListener('stalled', onKaInterrupted);
      kaAudioEl.addEventListener('suspend', onKaInterrupted);
      kaAudioEl.addEventListener('ended', onKaInterrupted);
      doc.body.appendChild(kaAudioEl);
      try {
        if (win.navigator?.mediaSession) {
          win.navigator.mediaSession.metadata = null;
          win.navigator.mediaSession.playbackState = 'none';
        }
      } catch (_) {}
      try {
        await kaAudioEl.play();
        kaNeedsGesture = false;
      } catch (_) {
        kaNeedsGesture = true;
      }
    } else {
      // 轻保活（不占灵动岛）：纯 WebAudio + WebLock + 切回自动补拉
      const AC = win.AudioContext || win.webkitAudioContext;
      if (AC) {
        try {
          kaAudioCtx = new AC();
          const gain = kaAudioCtx.createGain();
          gain.gain.value = 0.00001;
          kaOsc = kaAudioCtx.createOscillator();
          kaOsc.frequency.value = 1;
          kaOsc.connect(gain);
          gain.connect(kaAudioCtx.destination);
          kaOsc.start();
          if (kaAudioCtx.state === 'suspended') await kaAudioCtx.resume();
          kaNeedsGesture = kaAudioCtx.state !== 'running';
        } catch (_) {
          kaNeedsGesture = false;
        }
      }
    }

    await requestKaWakeLock();
    updateKeepAliveUI();
  };

  // 切回前台时仅轻量刷新统计，不再调用 reloadCurrentChat 导致酒馆画面闪烁重载
  const syncChatAfterBackground = async () => {
    try {
      updateStats();
      if (config.maskEnabled) setTimeout(applyMasks, 260);
    } catch (_) {}
  };

  const onKeepAliveVisibility = () => {
    if (!config.keepAlive) return;
    if (doc.hidden) {
      kaHiddenAt = Date.now();
    } else {
      const awayMs = kaHiddenAt ? (Date.now() - kaHiddenAt) : 0;
      kaHiddenAt = 0;
      acquireWebLock();
      requestKaWakeLock();
      if (kaAudioEl && kaAudioEl.paused) {
        kaAudioEl.play().then(() => {
          kaNeedsGesture = false;
          updateKeepAliveUI();
        }).catch(() => {});
      }
      if (kaAudioCtx && kaAudioCtx.state === 'suspended') {
        kaAudioCtx.resume().then(() => {
          kaNeedsGesture = false;
          updateKeepAliveUI();
        }).catch(() => {});
      }
      if (awayMs > 18000) {
        setTimeout(syncChatAfterBackground, 900);
      }
    }
  };
  doc.addEventListener('visibilitychange', onKeepAliveVisibility);

  const onKeepAliveGesture = () => {
    if (config.keepAlive && kaNeedsGesture) {
      startKeepAlive();
    }
  };
  doc.addEventListener('pointerdown', onKeepAliveGesture, { passive: true });

  // ==================== 胶囊定位、无卡顿双击召唤、面板移动与缩放 ====================
  let cachedBadgeW = 78;
  let cachedBadgeH = 30;
  let lastSummonAt = 0;

  const scheduleSaveConfig = () => {
    clearTimeout(deferredSaveTimer);
    deferredSaveTimer = setTimeout(saveConfig, 120);
  };

  const applyBadgePosition = (measureNow = false) => {
    const w = win.innerWidth;
    const h = win.innerHeight;
    if (measureNow && !config.fullHidden && !config.hidden) {
      const mw = badge.offsetWidth;
      const mh = badge.offsetHeight;
      if (mw > 0) cachedBadgeW = mw;
      if (mh > 0) cachedBadgeH = mh;
    }

    if (config.posX === null) config.posX = w - cachedBadgeW - 14;
    config.posX = clamp(config.posX, 8, Math.max(8, w - cachedBadgeW - 8));
    config.posY = clamp(config.posY, 8, Math.max(8, h - cachedBadgeH - 8));

    badge.style.transform = `translate3d(${Math.round(config.posX)}px, ${Math.round(config.posY)}px, 0)`;

    edgeTab.style.top = `${clamp(config.posY, 40, h - 84)}px`;
    edgeTab.classList.toggle('side-left', config.dockSide === 'left');
    edgeTab.classList.toggle('side-right', config.dockSide === 'right');

    if (config.fullHidden) {
      badge.classList.add('hidden');
      edgeTab.classList.remove('visible');
    } else {
      edgeTab.classList.toggle('visible', config.hidden);
      badge.classList.toggle('hidden', config.hidden);
    }
  };

  const summonFromFullHidden = () => {
    if (!config.fullHidden) return;
    const now = Date.now();
    if (now - lastSummonAt < 450) return;
    lastSummonAt = now;

    config.fullHidden = false;
    config.hidden = false;
    win.requestAnimationFrame(() => {
      try {
        const sel = win.getSelection?.();
        if (sel && sel.rangeCount > 0) sel.removeAllRanges();
      } catch (_) {}
      applyBadgePosition(false);
    });
    scheduleSaveConfig();
  };

  const isInteractiveTarget = (el) => {
    if (!el || !el.closest) return false;
    return Boolean(el.closest('input, textarea, select, button, a, [contenteditable="true"], #st-tb-root'));
  };

  let lastSummonTouchEndAt = 0;
  let desktopSummonTap = { count: 0, time: 0, x: 0, y: 0 };
  const onDocDblClick = (e) => {
    if (!config.fullHidden) return;
    if (isInteractiveTarget(e.target)) return;
    const now = Date.now();
    if (now - lastSummonTouchEndAt < 650) return;
    if (now - desktopSummonTap.time < 480 && Math.hypot(e.clientX - desktopSummonTap.x, e.clientY - desktopSummonTap.y) < 45) {
      desktopSummonTap.count += 1;
      desktopSummonTap.time = now;
      desktopSummonTap.x = e.clientX;
      desktopSummonTap.y = e.clientY;
    } else {
      desktopSummonTap = { count: 1, time: now, x: e.clientX, y: e.clientY };
    }
    if (desktopSummonTap.count >= 3) {
      desktopSummonTap.count = 0;
      desktopSummonTap.time = 0;
      e.preventDefault();
      summonFromFullHidden();
    }
  };
  doc.addEventListener('click', onDocDblClick);

  let lastTouchTap = { count: 0, time: 0, x: 0, y: 0 };
  const onDocTouchEnd = (e) => {
    if (!config.fullHidden) return;
    if (isInteractiveTarget(e.target)) return;
    const t = e.changedTouches?.[0];
    if (!t) return;
    const now = Date.now();
    lastSummonTouchEndAt = now;
    if (now - lastTouchTap.time < 480 && Math.hypot(t.clientX - lastTouchTap.x, t.clientY - lastTouchTap.y) < 45) {
      lastTouchTap.count += 1;
      lastTouchTap.time = now;
      lastTouchTap.x = t.clientX;
      lastTouchTap.y = t.clientY;
    } else {
      lastTouchTap = { count: 1, time: now, x: t.clientX, y: t.clientY };
    }
    if (lastTouchTap.count >= 3) {
      lastTouchTap.count = 0;
      lastTouchTap.time = 0;
      summonFromFullHidden();
    }
  };
  doc.addEventListener('touchend', onDocTouchEnd, { passive: true });

  const applyPanelSize = () => {
    const maxW = Math.max(260, win.innerWidth - 16);
    const maxH = Math.max(260, win.innerHeight - 20);
    const pw = clamp(Number(config.panelW) || 316, 260, maxW);
    const ph = clamp(Number(config.panelH) || 520, 260, maxH);
    panel.style.width = `${pw}px`;
    panel.style.height = `${ph}px`;
    return { pw, ph };
  };

  const positionPanel = () => {
    const w = win.innerWidth;
    const h = win.innerHeight;
    const { pw, ph } = applyPanelSize();

    let left;
    let top;
    if (config.panelX !== null && config.panelY !== null) {
      left = clamp(config.panelX, 8, Math.max(8, w - pw - 8));
      top = clamp(config.panelY, 8, Math.max(8, h - ph - 8));
    } else if (w < 520) {
      left = clamp(Math.round((w - pw) / 2), 8, Math.max(8, w - pw - 8));
      top = clamp(Math.round(h * 0.1), 10, Math.max(10, h - ph - 10));
    } else {
      const bx = config.posX ?? (w - 90);
      const by = config.posY ?? 54;
      left = clamp(bx + 76 - pw, 10, Math.max(10, w - pw - 10));
      top = clamp(by + 38, 10, Math.max(10, h - ph - 10));
    }
    panel.style.left = `${left}px`;
    panel.style.top = `${top}px`;
  };

  const resetPanelLayout = () => {
    config.panelX = null;
    config.panelY = null;
    config.panelW = defaultConfig.panelW;
    config.panelH = defaultConfig.panelH;
    saveConfig();
    positionPanel();
  };

  let panelDrag = null;
  panelHeader.addEventListener('pointerdown', (e) => {
    if (e.button !== 0 && e.pointerType === 'mouse') return;
    if (e.target.closest('button')) return;
    panelHeader.setPointerCapture(e.pointerId);
    const rect = panel.getBoundingClientRect();
    panelDrag = {
      id: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      origLeft: rect.left,
      origTop: rect.top,
      width: rect.width,
      height: rect.height,
    };
    panelHeader.classList.add('dragging');
  });

  panelHeader.addEventListener('pointermove', (e) => {
    if (!panelDrag || panelDrag.id !== e.pointerId) return;
    const left = clamp(panelDrag.origLeft + (e.clientX - panelDrag.startX), 8, Math.max(8, win.innerWidth - panelDrag.width - 8));
    const top = clamp(panelDrag.origTop + (e.clientY - panelDrag.startY), 8, Math.max(8, win.innerHeight - panelDrag.height - 8));
    panel.style.left = `${Math.round(left)}px`;
    panel.style.top = `${Math.round(top)}px`;
  });

  const endPanelDrag = (e) => {
    if (!panelDrag || panelDrag.id !== e.pointerId) return;
    const rect = panel.getBoundingClientRect();
    config.panelX = Math.round(rect.left);
    config.panelY = Math.round(rect.top);
    saveConfig();
    panelHeader.classList.remove('dragging');
    try { panelHeader.releasePointerCapture(e.pointerId); } catch (_) {}
    panelDrag = null;
  };
  panelHeader.addEventListener('pointerup', endPanelDrag);
  panelHeader.addEventListener('pointercancel', endPanelDrag);
  panelHeader.addEventListener('dblclick', (e) => {
    if (!e.target.closest('button')) resetPanelLayout();
  });

  let resizeState = null;
  resizeHandles.forEach((handle) => {
    handle.addEventListener('pointerdown', (e) => {
      if (e.button !== 0 && e.pointerType === 'mouse') return;
      e.preventDefault();
      e.stopPropagation();
      handle.setPointerCapture(e.pointerId);
      const rect = panel.getBoundingClientRect();
      resizeState = {
        id: e.pointerId,
        handle,
        dir: handle.dataset.dir,
        startX: e.clientX,
        startY: e.clientY,
        origW: rect.width,
        origH: rect.height,
        origLeft: rect.left,
        origTop: rect.top,
      };
    });

    handle.addEventListener('pointermove', (e) => {
      if (!resizeState || resizeState.id !== e.pointerId) return;
      const dx = e.clientX - resizeState.startX;
      const dy = e.clientY - resizeState.startY;
      const dir = resizeState.dir;
      let newW = resizeState.origW;
      let newH = resizeState.origH;
      let newLeft = resizeState.origLeft;

      if (dir.includes('r')) newW = clamp(resizeState.origW + dx, 260, Math.max(260, win.innerWidth - resizeState.origLeft - 8));
      if (dir.includes('l')) {
        newW = clamp(resizeState.origW - dx, 260, Math.max(260, resizeState.origLeft + resizeState.origW - 8));
        newLeft = resizeState.origLeft + (resizeState.origW - newW);
      }
      if (dir.includes('b')) newH = clamp(resizeState.origH + dy, 260, Math.max(260, win.innerHeight - resizeState.origTop - 8));

      panel.style.width = `${Math.round(newW)}px`;
      panel.style.height = `${Math.round(newH)}px`;
      if (dir.includes('l')) panel.style.left = `${Math.round(newLeft)}px`;
    });

    const endResize = (e) => {
      if (!resizeState || resizeState.id !== e.pointerId) return;
      const rect = panel.getBoundingClientRect();
      config.panelW = Math.round(rect.width);
      config.panelH = Math.round(rect.height);
      if (config.panelX !== null) config.panelX = Math.round(rect.left);
      saveConfig();
      try { resizeState.handle.releasePointerCapture(e.pointerId); } catch (_) {}
      resizeState = null;
    };

    handle.addEventListener('pointerup', endResize);
    handle.addEventListener('pointercancel', endResize);
  });

  resizeBR.addEventListener('dblclick', resetPanelLayout);

  let dragState = null;
  let badgeLongPressTimer = null;
  badge.addEventListener('contextmenu', (e) => {
    e.preventDefault();
    if (typeof toggleQuickDock === 'function') toggleQuickDock(true);
  });
  badge.addEventListener('pointerdown', (e) => {
    if (e.button !== 0 && e.pointerType === 'mouse') return;
    badge.setPointerCapture(e.pointerId);
    const rect = badge.getBoundingClientRect();
    if (rect.width > 0) cachedBadgeW = rect.width;
    if (rect.height > 0) cachedBadgeH = rect.height;
    dragState = {
      id: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      origX: config.posX ?? rect.left,
      origY: config.posY ?? rect.top,
      moved: false,
      longPressed: false,
    };
    clearTimeout(badgeLongPressTimer);
    badgeLongPressTimer = setTimeout(() => {
      if (dragState && !dragState.moved) {
        dragState.longPressed = true;
        if (typeof toggleQuickDock === 'function') toggleQuickDock(true);
      }
    }, 280);
  });

  badge.addEventListener('pointermove', (e) => {
    if (!dragState || dragState.id !== e.pointerId) return;
    const dx = e.clientX - dragState.startX;
    const dy = e.clientY - dragState.startY;
    if (!dragState.moved && Math.hypot(dx, dy) > 14) {
      dragState.moved = true;
      clearTimeout(badgeLongPressTimer);
      if (typeof toggleQuickDock === 'function') toggleQuickDock(false);
      badge.classList.add('dragging');
    }
    if (dragState.moved) {
      config.posX = clamp(dragState.origX + dx, 8, win.innerWidth - cachedBadgeW - 8);
      config.posY = clamp(dragState.origY + dy, 8, win.innerHeight - cachedBadgeH - 8);
      badge.style.transform = `translate3d(${Math.round(config.posX)}px, ${Math.round(config.posY)}px, 0)`;
    }
  });

  const finishDrag = (e) => {
    if (!dragState || dragState.id !== e.pointerId) return;
    clearTimeout(badgeLongPressTimer);
    const wasMoved = dragState.moved;
    const wasLong = dragState.longPressed;
    dragState = null;
    badge.classList.remove('dragging');
    try { badge.releasePointerCapture(e.pointerId); } catch (_) {}

    if (wasMoved) {
      config.dockSide = (config.posX + (cachedBadgeW / 2)) < (win.innerWidth / 2) ? 'left' : 'right';
      saveConfig();
      applyBadgePosition(false);
    } else if (!wasLong) {
      if (typeof toggleQuickDock === 'function') toggleQuickDock(false);
      togglePanel(!panelOpen);
    }
  };

  badge.addEventListener('pointerup', finishDrag);
  badge.addEventListener('pointercancel', finishDrag);

  edgeTab.addEventListener('click', () => {
    config.hidden = false;
    config.fullHidden = false;
    saveConfig();
    applyBadgePosition(false);
  });

  // ==================== 统计、搜索、书签、严格可见正文导出 ====================
  const getCurrentCharacter = () => {
    const ctx = getContext();
    if (!ctx || ctx.groupId) return null;
    if (ctx.characterId === undefined || ctx.characterId === null) return null;
    return ctx.characters?.[ctx.characterId] || null;
  };

  const cleanFileName = (name) => String(name || '').replace(/\.jsonl$/i, '');

  const getCurrentChatKey = () => {
    const ctx = getContext();
    if (!ctx) return null;
    if (ctx.groupId) return `group::${ctx.groupId}`;
    const char = getCurrentCharacter();
    if (!char || !ctx.chatId) return null;
    return `${char.avatar || char.name}::${cleanFileName(ctx.chatId)}`;
  };

  const scrollAndFlashMes = (mesid) => {
    const target = doc.querySelector(`#chat .mes[mesid="${mesid}"]`);
    if (!target) return false;
    target.scrollIntoView({ behavior: 'smooth', block: 'center' });
    doc.querySelectorAll('#chat .mes.st-tb-flash').forEach(el => el.classList.remove('st-tb-flash'));
    target.classList.add('st-tb-flash');
    clearTimeout(flashTimer);
    flashTimer = setTimeout(() => target.classList.remove('st-tb-flash'), 1800);
    return true;
  };

  const updateStats = () => {
    const ctx = getContext();
    const chat = Array.isArray(ctx?.chat) ? ctx.chat : [];
    const validMsgs = chat.filter(m => m && !m.is_system);
    let totalChars = 0;
    for (const m of validMsgs) {
      if (typeof m.mes === 'string') totalChars += m.mes.replace(/\s+/g, '').length;
    }
    floorText.textContent = `${validMsgs.length} 层`;
    statFloor.textContent = `${validMsgs.length}`;
    statWords.textContent = totalChars >= 10000
      ? `${(totalChars / 10000).toFixed(1)}万`
      : `${totalChars}`;
  };

  const runSearch = (step = 1) => {
    const kw = searchInput.value.trim().toLowerCase();
    if (!kw) {
      searchMatches = [];
      searchIndex = -1;
      searchStatusEl.textContent = '';
      return;
    }
    const ctx = getContext();
    const chat = Array.isArray(ctx?.chat) ? ctx.chat : [];
    const found = [];
    chat.forEach((m, idx) => {
      if (!m || m.is_system) return;
      if (typeof m.mes === 'string' && m.mes.toLowerCase().includes(kw)) found.push(idx);
    });

    const same = searchMatches.length === found.length && searchMatches.every((v, i) => v === found[i]);
    searchMatches = found;

    if (!searchMatches.length) {
      searchIndex = -1;
      searchStatusEl.textContent = '无匹配';
      return;
    }

    searchIndex = (!same || searchIndex < 0)
      ? (step > 0 ? 0 : searchMatches.length - 1)
      : (searchIndex + step + searchMatches.length) % searchMatches.length;

    const targetMesId = searchMatches[searchIndex];
    const ok = scrollAndFlashMes(targetMesId);
    searchStatusEl.textContent = ok
      ? `${searchIndex + 1}/${searchMatches.length} (#${targetMesId})`
      : `${searchIndex + 1}/${searchMatches.length} (#${targetMesId} 未加载)`;
  };

  const getCurrentVisibleMesId = () => {
    const chatEl = doc.getElementById('chat');
    if (!chatEl) return null;
    const rect = chatEl.getBoundingClientRect();
    const midY = rect.top + rect.height * 0.45;
    const items = Array.from(chatEl.querySelectorAll('.mes[mesid]'));
    if (!items.length) return null;
    let best = items[items.length - 1];
    let bestDist = Infinity;
    for (const el of items) {
      const r = el.getBoundingClientRect();
      const dist = Math.abs((r.top + r.bottom) / 2 - midY);
      if (dist < bestDist) {
        bestDist = dist;
        best = el;
      }
    }
    return best.getAttribute('mesid');
  };

  const renderBookmarks = () => { if (!bmListEl || !bmCountEl) return;
    const key = getCurrentChatKey();
    const list = key && Array.isArray(bookmarkMap[key]) ? bookmarkMap[key] : [];
    bmCountEl.textContent = `${list.length} 个`;
    bmListEl.innerHTML = '';

    list.forEach((bm, idx) => {
      const item = doc.createElement('div');
      item.className = 'st-tb-list-item';

      const link = doc.createElement('span');
      link.className = 'st-tb-list-link';
      link.textContent = `#${bm.mesid}${bm.note ? ` · ${bm.note}` : ''}`;
      link.title = '点击跳转到此楼层';
      link.addEventListener('click', () => {
        if (!scrollAndFlashMes(bm.mesid)) {
          const old = link.textContent;
          link.textContent = `#${bm.mesid} 尚未向上加载`;
          setTimeout(() => (link.textContent = old), 1400);
        }
      });

      const del = doc.createElement('button');
      del.className = 'st-tb-list-del';
      del.type = 'button';
      del.textContent = '×';
      del.title = '删除书签';
      del.addEventListener('click', () => {
        bookmarkMap[key].splice(idx, 1);
        saveBookmarks();
        renderBookmarks();
      });

      item.append(link, del);
      bmListEl.appendChild(item);
    });
  };

  // ==================== 输入框防丢失本地草稿箱 ====================
  let draftInputTimer = null;
  let boundSendTextarea = null;

  const formatDraftTime = (ts) => {
    const d = new Date(ts);
    const hh = String(d.getHours()).padStart(2, '0');
    const mm = String(d.getMinutes()).padStart(2, '0');
    return `${hh}:${mm}`;
  };

  const renderDrafts = () => {
    if (!draftListEl) return;
    draftListEl.innerHTML = '';
    if (!draftList.length) {
      draftListEl.innerHTML = '<div class="st-tb-tip" style="margin-top:0;">在酒馆输入框打字时会自动暂存，防误刷新丢失。</div>';
      return;
    }
    draftList.forEach((item, idx) => {
      const row = doc.createElement('div');
      row.className = 'st-tb-list-item';

      const link = doc.createElement('span');
      link.className = 'st-tb-list-link';
      const preview = item.text.replace(/\s+/g, ' ').slice(0, 26);
      link.textContent = `[${formatDraftTime(item.ts)}] ${preview}`;
      link.title = item.text;
      link.addEventListener('click', () => {
        const ta = doc.getElementById('send_textarea');
        if (!ta) return;
        ta.value = item.text;
        ta.dispatchEvent(new Event('input', { bubbles: true }));
        ta.focus();
        togglePanel(false);
      });

      const del = doc.createElement('button');
      del.className = 'st-tb-list-del';
      del.type = 'button';
      del.textContent = '×';
      del.title = '删除草稿';
      del.addEventListener('click', () => {
        draftList.splice(idx, 1);
        saveDrafts();
        renderDrafts();
      });

      row.append(link, del);
      draftListEl.appendChild(row);
    });
  };

  const captureInputDraft = (forceNew = false) => {
    const ta = doc.getElementById('send_textarea');
    const text = ta ? String(ta.value || '').trim() : '';
    if (!text) return;
    const now = Date.now();
    if (!forceNew && draftList.length && (now - draftList[0].ts < 120000 || draftList[0].text === text)) {
      draftList[0].text = text;
      draftList[0].ts = now;
    } else {
      draftList = draftList.filter(d => d.text !== text);
      draftList.unshift({ text, ts: now });
      if (draftList.length > 8) draftList = draftList.slice(0, 8);
    }
    saveDrafts();
    if (panelOpen) renderDrafts();
  };

  const onSendTextareaInput = () => {
    clearTimeout(draftInputTimer);
    draftInputTimer = setTimeout(() => captureInputDraft(false), 500);
  };

  const attachDraftListener = () => { return;
    const ta = doc.getElementById('send_textarea');
    if (ta && ta !== boundSendTextarea) {
      if (boundSendTextarea) boundSendTextarea.removeEventListener('input', onSendTextareaInput);
      boundSendTextarea = ta;
      boundSendTextarea.addEventListener('input', onSendTextareaInput);
    }
  };

  if (draftSaveNowBtn) draftSaveNowBtn.addEventListener('click', () => {
    captureInputDraft(true);
    renderDrafts();
  });

  const addBookmark = () => { if (!bmNoteInput) return;
    const key = getCurrentChatKey();
    if (!key) return;
    const mesid = getCurrentVisibleMesId();
    if (mesid === null) return;
    const note = bmNoteInput.value.trim();
    if (!Array.isArray(bookmarkMap[key])) bookmarkMap[key] = [];
    const existing = bookmarkMap[key].find(b => String(b.mesid) === String(mesid));
    if (existing) {
      existing.note = note || existing.note;
    } else {
      bookmarkMap[key].push({ mesid: Number(mesid), note });
      bookmarkMap[key].sort((a, b) => a.mesid - b.mesid);
    }
    bmNoteInput.value = '';
    saveBookmarks();
    renderBookmarks();
  };

  const jumpToLastUserMsg = () => {
    const userMsgs = Array.from(doc.querySelectorAll('#chat .mes[is_user="true"]'));
    if (!userMsgs.length) return;
    const last = userMsgs[userMsgs.length - 1];
    const mesid = last.getAttribute('mesid');
    if (mesid !== null) {
      scrollAndFlashMes(mesid);
      togglePanel(false);
    }
  };

  const BLOCK_TAGS = new Set(['P', 'DIV', 'BR', 'LI', 'BLOCKQUOTE', 'H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'TR', 'HR']);
  const SKIP_TAGS = new Set(['STYLE', 'SCRIPT', 'NOSCRIPT', 'TEMPLATE', 'TEXTAREA', 'INPUT', 'BUTTON', 'SVG', 'CANVAS', 'IFRAME', 'SELECT']);

  const isNodeVisuallyHidden = (el) => {
    if (!el || el.nodeType !== 1) return false;
    if (el.hidden || el.getAttribute('aria-hidden') === 'true') return true;
    const cls = el.classList;
    if (
      cls.contains('mes_edit_textarea') ||
      cls.contains('edit_textarea') ||
      cls.contains('mes_buttons') ||
      cls.contains('extraMesButtons') ||
      cls.contains('swipes-counter')
    ) return true;
    if (el.tagName === 'DETAILS' && !el.open) return true;
    const cs = win.getComputedStyle(el);
    if (
      cs.display === 'none' ||
      cs.visibility === 'hidden' ||
      cs.visibility === 'collapse' ||
      parseFloat(cs.opacity) === 0 ||
      parseFloat(cs.fontSize) === 0
    ) return true;
    if (el.tagName !== 'BR') {
      const rect = el.getBoundingClientRect();
      if (rect.width === 0 && rect.height === 0) return true;
    }
    return false;
  };

  const extractVisibleNodeText = (node) => {
    if (!node) return '';
    if (node.nodeType === 3) return node.nodeValue || '';
    if (node.nodeType !== 1) return '';
    const tag = node.tagName;
    if (SKIP_TAGS.has(tag)) return '';
    if (isNodeVisuallyHidden(node)) return '';
    if (tag === 'BR') return '\n';

    let out = '';
    for (const child of node.childNodes) {
      out += extractVisibleNodeText(child);
    }
    if (BLOCK_TAGS.has(tag) && out.trim()) return `\n${out.trim()}\n`;
    return out;
  };

  const matchExportFilter = (mesid) => {
    const mode = exportModeSelect.value;
    if (mode === 'all') return true;
    const idNum = Number(mesid);
    if (!Number.isFinite(idNum)) return false;

    if (mode === 'single') {
      const raw = exportSingleInput.value.trim();
      if (!raw) return false;
      const set = new Set(
        raw.split(/[\s,，、;；]+/).map(s => Number(s.trim())).filter(n => Number.isFinite(n))
      );
      return set.has(idNum);
    }

    if (mode === 'range') {
      const fromVal = exportFromInput.value.trim();
      const toVal = exportToInput.value.trim();
      const from = fromVal === '' ? -Infinity : Number(fromVal);
      const to = toVal === '' ? Infinity : Number(toVal);
      if (Number.isNaN(from) || Number.isNaN(to)) return false;
      const min = Math.min(from, to);
      const max = Math.max(from, to);
      return idNum >= min && idNum <= max;
    }
    return true;
  };

  const buildVisibleTranscript = () => {
    const mesNodes = Array.from(doc.querySelectorAll('#chat .mes'));
    const charOnly = exportSpeakerSelect?.value === 'char';
    const blocks = [];
    for (const mes of mesNodes) {
      if (mes.getAttribute('is_system') === 'true') continue;
      if (charOnly && mes.getAttribute('is_user') === 'true') continue;
      const mesid = mes.getAttribute('mesid');
      if (!matchExportFilter(mesid)) continue;
      if (isNodeVisuallyHidden(mes)) continue;
      const textEl = mes.querySelector('.mes_text');
      if (!textEl || isNodeVisuallyHidden(textEl)) continue;
      const raw = extractVisibleNodeText(textEl)
        .replace(/\r\n/g, '\n')
        .replace(/[ \t]+\n/g, '\n')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
      if (!raw) continue;
      const nameEl = mes.querySelector('.name_text');
      const speaker = (nameEl?.innerText || mes.getAttribute('ch_name') || '角色').trim();
      blocks.push(`【${speaker}】\n${raw}`);
    }
    return { text: blocks.join('\n\n'), count: blocks.length };
  };

  const exportChatTxt = () => {
    const { text, count } = buildVisibleTranscript();
    const old = exportTxtBtn.textContent;
    if (!text) {
      exportTxtBtn.textContent = '无匹配可见层';
      setTimeout(() => (exportTxtBtn.textContent = old), 1300);
      return;
    }
    const ctx = getContext();
    const char = getCurrentCharacter();
    const speakerSuffix = exportSpeakerSelect?.value === 'char' ? '_仅Char' : '';
    const baseName = `${char?.name || 'chat'}_${cleanFileName(ctx?.chatId || Date.now())}${speakerSuffix}`.replace(/[\\/:*?"<>|]/g, '_');
    const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
    const url = win.URL.createObjectURL(blob);
    const a = doc.createElement('a');
    a.href = url;
    a.download = `${baseName}.txt`;
    doc.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => win.URL.revokeObjectURL(url), 1000);
    exportTxtBtn.textContent = `已导出 ${count} 层`;
    setTimeout(() => (exportTxtBtn.textContent = old), 1300);
  };

  const copyChatTxt = async () => {
    const { text, count } = buildVisibleTranscript();
    const oldText = copyTxtBtn.textContent;
    if (!text) {
      copyTxtBtn.textContent = '无匹配可见层';
      setTimeout(() => (copyTxtBtn.textContent = oldText), 1300);
      return;
    }
    try {
      if (win.navigator?.clipboard?.writeText) {
        await win.navigator.clipboard.writeText(text);
      } else {
        const ta = doc.createElement('textarea');
        ta.value = text;
        ta.style.position = 'fixed';
        ta.style.opacity = '0';
        doc.body.appendChild(ta);
        ta.select();
        doc.execCommand('copy');
        ta.remove();
      }
      copyTxtBtn.textContent = `已复制 ${count} 层`;
    } catch (_) {
      copyTxtBtn.textContent = '复制失败';
    }
    setTimeout(() => (copyTxtBtn.textContent = oldText), 1300);
  };

  // ==================== 聊天文件管理 ====================
  const fetchCharacterChats = async () => {
    const ctx = getContext();
    const char = getCurrentCharacter();
    if (!ctx || !char || !char.avatar) {
      chatListCache = [];
      statChats.textContent = '-';
      chatCharInfo.textContent = ctx?.groupId ? '群聊暂不支持管理记录' : '未选择角色';
      renderChatList();
      return;
    }

    chatCharInfo.textContent = `${char.name} · 读取中...`;
    try {
      const headers = typeof ctx.getRequestHeaders === 'function'
        ? ctx.getRequestHeaders()
        : { 'Content-Type': 'application/json' };

      const res = await win.fetch('/api/characters/chats', {
        method: 'POST',
        headers,
        body: JSON.stringify({ avatar_url: char.avatar }),
      });

      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      const list = Array.isArray(data) ? data : Object.values(data || {});
      chatListCache = list.filter(item => item && item.file_name);
      statChats.textContent = `${chatListCache.length}`;
      chatCharInfo.textContent = `${char.name} · 共 ${chatListCache.length} 个记录`;
      renderChatList();
    } catch (_) {
      chatCharInfo.textContent = `${char.name} · 读取失败`;
      chatListEl.innerHTML = `<div class="st-tb-empty">读取聊天列表失败，请点刷新重试</div>`;
    }
  };

  const switchChatFile = async (fileName) => {
    const ctx = getContext();
    if (!ctx || typeof ctx.openCharacterChat !== 'function') return;
    const clean = cleanFileName(fileName);
    try {
      await ctx.openCharacterChat(clean);
      renamingFile = null;
      await fetchCharacterChats();
      updateStats();
      renderBookmarks();
    } catch (_) {}
  };

  const renameChatFile = async (oldFileName, newRawName) => {
    const ctx = getContext();
    const char = getCurrentCharacter();
    if (!ctx || !char) return;

    const oldClean = cleanFileName(oldFileName);
    const newClean = cleanFileName(newRawName).trim().replace(/[\\/:*?"<>|]/g, '');
    if (!newClean || newClean === oldClean) {
      renamingFile = null;
      renderChatList();
      return;
    }

    const headers = typeof ctx.getRequestHeaders === 'function'
      ? ctx.getRequestHeaders()
      : { 'Content-Type': 'application/json' };
    const isCurrent = cleanFileName(ctx.chatId) === oldClean;

    try {
      const res = await win.fetch('/api/chats/rename', {
        method: 'POST',
        headers,
        body: JSON.stringify({
          is_group: false,
          avatar_url: char.avatar,
          original_file: `${oldClean}.jsonl`,
          renamed_file: `${newClean}.jsonl`,
        }),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      renamingFile = null;
      if (isCurrent && typeof ctx.openCharacterChat === 'function') {
        await ctx.openCharacterChat(newClean);
      }
      await fetchCharacterChats();
    } catch (_) {
      chatCharInfo.textContent = '重命名失败，请检查名称是否重复';
    }
  };

  const renderChatList = () => {
    const ctx = getContext();
    const currentId = cleanFileName(ctx?.chatId);
    const filter = chatFilterText.trim().toLowerCase();

    const filtered = filter
      ? chatListCache.filter(item => cleanFileName(item.file_name).toLowerCase().includes(filter))
      : chatListCache;

    if (!filtered.length) {
      chatListEl.innerHTML = `<div class="st-tb-empty">${filter ? '没有匹配的聊天记录' : '暂无聊天文件'}</div>`;
      return;
    }

    chatListEl.innerHTML = '';
    for (const item of filtered) {
      const clean = cleanFileName(item.file_name);
      const isCurrent = clean === currentId;

      const row = doc.createElement('div');
      row.className = `st-tb-chat-item${isCurrent ? ' current' : ''}`;

      if (renamingFile === item.file_name) {
        const editRow = doc.createElement('div');
        editRow.className = 'st-tb-row';

        const input = doc.createElement('input');
        input.className = 'st-tb-input';
        input.type = 'text';
        input.value = clean;

        const saveBtn = doc.createElement('button');
        saveBtn.className = 'st-tb-btn primary';
        saveBtn.type = 'button';
        saveBtn.textContent = '保存';
        saveBtn.addEventListener('click', () => renameChatFile(item.file_name, input.value));

        const cancelBtn = doc.createElement('button');
        cancelBtn.className = 'st-tb-btn';
        cancelBtn.type = 'button';
        cancelBtn.textContent = '取消';
        cancelBtn.addEventListener('click', () => {
          renamingFile = null;
          renderChatList();
        });

        input.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') renameChatFile(item.file_name, input.value);
          if (e.key === 'Escape') {
            renamingFile = null;
            renderChatList();
          }
        });

        editRow.append(input, saveBtn, cancelBtn);
        row.appendChild(editRow);
        setTimeout(() => input.focus(), 0);
      } else {
        const top = doc.createElement('div');
        top.className = 'st-tb-chat-top';

        const nameEl = doc.createElement('div');
        nameEl.className = 'st-tb-chat-name';
        nameEl.textContent = clean;
        nameEl.title = '点击切换到此聊天';
        nameEl.addEventListener('click', () => {
          if (!isCurrent) switchChatFile(item.file_name);
        });

        const renameBtn = doc.createElement('button');
        renameBtn.className = 'st-tb-mini-btn';
        renameBtn.type = 'button';
        renameBtn.textContent = '重命名';
        renameBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          renamingFile = item.file_name;
          renderChatList();
        });

        top.appendChild(nameEl);
        if (isCurrent) {
          const tag = doc.createElement('span');
          tag.className = 'st-tb-chat-badge';
          tag.textContent = '当前';
          top.appendChild(tag);
        }
        top.appendChild(renameBtn);

        const sub = doc.createElement('div');
        sub.className = 'st-tb-chat-sub';
        const metaLeft = item.chat_items !== undefined ? `${item.chat_items} 条` : (item.file_size || '');
        const metaRight = item.last_mes ? String(item.last_mes).slice(0, 16) : '';
        sub.innerHTML = `<span>${metaLeft}</span><span>${metaRight}</span>`;

        row.append(top, sub);
      }

      chatListEl.appendChild(row);
    }
  };

  // ==================== 开场白一览快速选择器 & 当前生效世界书 ====================
  const getCharacterGreetings = () => {
    const ctx = getContext();
    const char = getCurrentCharacter();
    const list = [];
    if (char) {
      const first = char.first_mes || char.data?.first_mes || '';
      if (first) list.push(first);
      const alts = Array.isArray(char.data?.alternate_greetings)
        ? char.data.alternate_greetings
        : (Array.isArray(char.alternate_greetings) ? char.alternate_greetings : []);
      alts.forEach(g => {
        if (typeof g === 'string' && g.trim()) list.push(g);
      });
    }
    // 若第 0 层已有 swipes 且数量更多，以 swipes 为准
    const msg0 = ctx?.chat?.[0];
    if (msg0 && Array.isArray(msg0.swipes) && msg0.swipes.length > list.length) {
      return msg0.swipes;
    }
    return list;
  };

  let expandedGreetIdx = -1;

  const renderGreetingsList = () => {
    const ctx = getContext();
    const greetings = getCharacterGreetings();
    greetTitleEl.textContent = `开场白一览 (${greetings.length} 版)`;
    greetListEl.innerHTML = '';

    if (!greetings.length) {
      greetListEl.innerHTML = '<div class="st-tb-empty">当前角色暂无开场白</div>';
      return;
    }

    const msg0 = ctx?.chat?.[0];
    const currentIdx = Number.isFinite(msg0?.swipe_id) ? msg0.swipe_id : 0;
    const validMsgs = Array.isArray(ctx?.chat) ? ctx.chat.filter(m => m && !m.is_system) : [];
    const canSwitchDirect = validMsgs.length <= 1 && Boolean(msg0);

    greetings.forEach((raw, idx) => {
      const isExpanded = expandedGreetIdx === idx;
      const card = doc.createElement('div');
      card.className = `st-tb-greet-card${idx === currentIdx ? ' active' : ''}${isExpanded ? ' expanded' : ''}`;

      const top = doc.createElement('div');
      top.className = 'st-tb-greet-top';
      const title = doc.createElement('span');
      title.textContent = idx === 0 ? '开场白 #1 (默认)' : `开场白 #${idx + 1}`;
      const badgeEl = doc.createElement('span');
      badgeEl.className = 'st-tb-wb-tag';
      badgeEl.textContent = idx === currentIdx ? '当前' : (isExpanded ? '收起预览' : '展开预览');
      top.append(title, badgeEl);

      const cleanFull = String(raw || '')
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<[^>]+>/g, '')
        .replace(/\n{3,}/g, '\n\n')
        .trim();

      const prev = doc.createElement('div');
      prev.className = 'st-tb-greet-preview';
      prev.textContent = isExpanded
        ? (cleanFull.length > 900 ? `${cleanFull.slice(0, 900)}...` : cleanFull)
        : cleanFull.replace(/\s+/g, ' ');

      const actions = doc.createElement('div');
      actions.className = 'st-tb-greet-actions';

      if (canSwitchDirect && idx !== currentIdx) {
        const useBtn = doc.createElement('button');
        useBtn.type = 'button';
        useBtn.className = 'st-tb-btn primary';
        useBtn.style.flex = '1';
        useBtn.textContent = '确认切换此开场白';
        useBtn.addEventListener('click', async (e) => {
          e.stopPropagation();
          if (!ctx) return;
          try {
            if (!Array.isArray(msg0.swipes) || msg0.swipes.length < greetings.length) {
              msg0.swipes = [...greetings];
            }
            msg0.swipe_id = idx;
            msg0.mes = msg0.swipes[idx];
            if (typeof ctx.saveChat === 'function') await ctx.saveChat();
            if (typeof ctx.reloadCurrentChat === 'function') await ctx.reloadCurrentChat();
            expandedGreetIdx = -1;
            renderGreetingsList();
            updateStats();
            if (config.maskEnabled) setTimeout(applyMasks, 260);
          } catch (_) {}
        });
        actions.appendChild(useBtn);
      }

      const copyBtn = doc.createElement('button');
      copyBtn.type = 'button';
      copyBtn.className = 'st-tb-btn';
      copyBtn.style.flex = canSwitchDirect && idx !== currentIdx ? '0 0 auto' : '1';
      copyBtn.textContent = '复制全文';
      copyBtn.addEventListener('click', async (e) => {
        e.stopPropagation();
        try {
          if (win.navigator?.clipboard?.writeText) {
            await win.navigator.clipboard.writeText(String(raw || ''));
            copyBtn.textContent = '已复制';
            setTimeout(() => (copyBtn.textContent = '复制全文'), 1200);
          }
        } catch (_) {}
      });
      actions.appendChild(copyBtn);

      card.append(top, prev, actions);
      card.addEventListener('click', (e) => {
        if (e.target.closest('button')) return;
        if (isExpanded && e.target.closest('.st-tb-greet-preview')) return;
        expandedGreetIdx = isExpanded ? -1 : idx;
        renderGreetingsList();
      });
      greetListEl.appendChild(card);
    });

    if (!canSwitchDirect) {
      const tip = doc.createElement('div');
      tip.className = 'st-tb-tip';
      tip.style.marginTop = '0';
      tip.textContent = '当前已有后续对话，点卡片可展开预览或复制；新开聊天时可点「确认切换此开场白」。';
      greetListEl.appendChild(tip);
    }
  };

  greetToggleBtn.addEventListener('click', () => {
    const open = !greetListEl.classList.contains('open');
    greetListEl.classList.toggle('open', open);
    greetToggleBtn.textContent = open ? '收起' : '展开';
    if (open) renderGreetingsList();
  });

  const renderActiveWorldBooks = () => {
    const ctx = getContext();
    const char = getCurrentCharacter();
    const found = [];
    const seen = new Set();

    const addBook = (name, source) => {
      const clean = String(name || '').trim();
      if (!clean) return;
      const key = `${source}::${clean}`;
      if (seen.has(key)) return;
      seen.add(key);
      found.push({ name: clean, source });
    };

    const charPrimary = char?.data?.extensions?.world;
    if (charPrimary) addBook(charPrimary, '角色绑定');

    const charExtra = char?.data?.extensions?.extra_books;
    if (Array.isArray(charExtra)) {
      charExtra.forEach(b => addBook(b, '角色附加'));
    }

    const chatWb = ctx?.chatMetadata?.world_info;
    if (chatWb) addBook(chatWb, '当前聊天');

    // 读取酒馆全局世界书下拉框中已勾选的条目
    try {
      const opts = doc.querySelectorAll('#world_info option:checked');
      opts.forEach(opt => {
        const label = (opt.textContent || opt.value || '').trim();
        if (label) addBook(label, '全局开启');
      });
    } catch (_) {}

    wbCountEl.textContent = `${found.length} 本`;
    wbListEl.innerHTML = '';
    if (!found.length) {
      wbListEl.innerHTML = '<div class="st-tb-tip" style="margin-top:0;">当前未检测到开启或绑定的世界书。</div>';
      return;
    }
    found.forEach(item => {
      const row = doc.createElement('div');
      row.className = 'st-tb-wb-item';
      const nameEl = doc.createElement('span');
      nameEl.style.overflow = 'hidden';
      nameEl.style.textOverflow = 'ellipsis';
      nameEl.style.whiteSpace = 'nowrap';
      nameEl.textContent = item.name;
      nameEl.title = item.name;
      const tag = doc.createElement('span');
      tag.className = 'st-tb-wb-tag';
      tag.textContent = item.source;
      row.style.cursor = 'pointer';
      row.title = '点击跳转到世界书编辑：' + item.name;
      row.addEventListener('click', () => {
        if (typeof openWorldbookInEditor === 'function') openWorldbookInEditor(item.name);
      });
      row.append(nameEl, tag);
      wbListEl.appendChild(row);
    });
  };

  // ==================== 一键打码系统 ====================
  let chatObserver = null;

  const runWithoutObserve = (fn) => {
    try { fn(); } finally {
      if (chatObserver) chatObserver.takeRecords();
    }
  };

  const getMaskWordList = () => {
    const seen = new Set();
    return String(config.maskWords || '')
      .split(/[\n,，、;；]+/)
      .map(s => s.trim())
      .filter(s => {
        if (!s) return false;
        const k = s.toLowerCase();
        if (seen.has(k)) return false;
        seen.add(k);
        return true;
      })
      .sort((a, b) => b.length - a.length);
  };

  const getCustomMaskDisplay = (orig) => {
    const raw = String(config.maskCustomText ?? '').trim() || '○';
    if (config.maskRepeat) {
      const unit = Array.from(raw)[0] || '○';
      return unit.repeat(Math.max(1, Array.from(orig).length));
    }
    return raw;
  };

  const escapeRegExp = (str) => str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const clearMasks = () => {
    runWithoutObserve(() => {
      const nodes = doc.querySelectorAll('#chat .st-tb-mask');
      nodes.forEach(span => {
        const parent = span.parentNode;
        if (!parent) return;
        const orig = span.dataset.orig !== undefined ? span.dataset.orig : (span.textContent || '');
        parent.replaceChild(doc.createTextNode(orig), span);
        parent.normalize();
      });
    });
  };

  const applyMasks = () => {
    clearMasks();
    if (!config.maskEnabled) return;
    const words = getMaskWordList();
    if (!words.length) return;

    const regex = new RegExp(words.map(escapeRegExp).join('|'), 'gi');
    const containers = doc.querySelectorAll('#chat .mes_text');

    runWithoutObserve(() => {
      containers.forEach(container => {
        const walker = doc.createTreeWalker(container, NodeFilter.SHOW_TEXT, {
          acceptNode: (node) => {
            if (!node.nodeValue || !node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
            const p = node.parentElement;
            if (!p) return NodeFilter.FILTER_REJECT;
            const tag = p.tagName;
            if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'TEXTAREA' || tag === 'INPUT' || p.classList.contains('st-tb-mask')) {
              return NodeFilter.FILTER_REJECT;
            }
            return NodeFilter.FILTER_ACCEPT;
          },
        });

        const targets = [];
        let n;
        while ((n = walker.nextNode())) {
          regex.lastIndex = 0;
          if (regex.test(n.nodeValue)) targets.push(n);
        }

        targets.forEach(textNode => {
          const text = textNode.nodeValue;
          regex.lastIndex = 0;
          let lastIdx = 0;
          let match;
          const frag = doc.createDocumentFragment();

          while ((match = regex.exec(text)) !== null) {
            if (match.index > lastIdx) frag.appendChild(doc.createTextNode(text.slice(lastIdx, match.index)));
            const origWord = match[0];
            const span = doc.createElement('span');
            span.className = 'st-tb-mask';
            span.dataset.style = config.maskStyle;
            span.dataset.orig = origWord;
            span.title = '点击切换显示';

            if (config.maskStyle === 'custom') {
              const masked = getCustomMaskDisplay(origWord);
              span.dataset.masked = masked;
              span.textContent = masked;
            } else {
              span.textContent = origWord;
            }

            frag.appendChild(span);
            lastIdx = match.index + origWord.length;
          }
          if (lastIdx < text.length) frag.appendChild(doc.createTextNode(text.slice(lastIdx)));
          textNode.parentNode?.replaceChild(frag, textNode);
        });
      });
    });
  };

  // ==================== 防误触右滑新生成与重新生成（确认后才调用 API） ====================
  let guardBypassUntil = 0;
  let pendingConfirmAction = null;
  let guardTouchStart = null;

  const closeGuardConfirm = () => {
    pendingConfirmAction = null;
    confirmMask.classList.remove('open');
    const sw = root.querySelector('#st-tb-confirm-skip-wrap');
    if (sw) sw.classList.remove('show');
  };

  const openGuardConfirm = (title, desc, onConfirm, okLabel = '确认生成', isPixelBag = false) => {
    confirmTitleEl.textContent = title;
    confirmDescEl.textContent = desc;
    if (confirmOkBtn) confirmOkBtn.textContent = okLabel || (isPixelBag ? '确认' : '确认生成');
    const box = root.querySelector('#st-tb-confirm-box');
    if (box) {
      box.classList.toggle('pixel-mode', Boolean(isPixelBag));
      if (isPixelBag && typeof pupBagEl !== 'undefined' && pupBagEl) {
        const cs = win.getComputedStyle(pupBagEl);
        const pxBg = pupBagEl.style.background || cs.backgroundColor || '#faf6f7';
        const pxBd = pupBagEl.style.getPropertyValue('--px-border') || cs.getPropertyValue('--px-border') || cs.borderTopColor || '#bfa4ae';
        const pxFg = pupBagEl.style.getPropertyValue('--px-fg') || cs.getPropertyValue('--px-fg') || cs.color || '#54444a';
        const pxSoft = pupBagEl.style.getPropertyValue('--px-bg-soft') || cs.getPropertyValue('--px-bg-soft') || '#f3ebee';
        const pxCard = pupBagEl.style.getPropertyValue('--px-card') || cs.getPropertyValue('--px-card') || '#ffffff';
        box.style.background = pxBg;
        box.style.borderColor = pxBd.trim();
        box.style.color = pxFg.trim();
        box.style.setProperty('--px-bg', pxBg);
        box.style.setProperty('--px-border', pxBd.trim());
        box.style.setProperty('--px-fg', pxFg.trim());
        box.style.setProperty('--px-bg-soft', pxSoft.trim());
        box.style.setProperty('--px-card', pxCard.trim());
        if (confirmCancelBtn) { confirmCancelBtn.className = 'st-px-btn'; confirmCancelBtn.style.cssText = 'height:24px;padding:0 12px;font-size:11px;'; }
        if (confirmOkBtn) { confirmOkBtn.className = 'st-px-btn active care'; confirmOkBtn.style.cssText = 'height:24px;padding:0 12px;font-size:11px;'; }
      } else {
        box.style.background = '';
        box.style.borderColor = '';
        box.style.color = '';
        if (confirmCancelBtn) { confirmCancelBtn.className = 'st-tb-btn'; confirmCancelBtn.style.cssText = ''; }
        if (confirmOkBtn) { confirmOkBtn.className = 'st-tb-btn primary'; confirmOkBtn.style.cssText = ''; }
      }
    }
    pendingConfirmAction = onConfirm;
    confirmMask.classList.add('open');
  };

  confirmCancelBtn.addEventListener('click', closeGuardConfirm);
  confirmMask.addEventListener('click', (e) => {
    if (e.target === confirmMask) closeGuardConfirm();
  });
  confirmOkBtn.addEventListener('click', () => {
    const fn = pendingConfirmAction;
    closeGuardConfirm();
    if (typeof fn === 'function') {
      guardBypassUntil = Date.now() + 900;
      fn();
    }
  });

  // 判断右滑是否真的会调用 API（自动放行第 0 层切换开场白，以及浏览已有分支如 1/3 -> 2/3）
  const willSwipeRightGenerate = (mesEl) => {
    if (!mesEl) return false;
    const isLast = mesEl.classList.contains('last_mes') || mesEl === doc.querySelector('#chat .mes:last-of-type');
    if (!isLast) return false;
    if (mesEl.getAttribute('is_user') === 'true') return false;

    const mesid = Number(mesEl.getAttribute('mesid'));
    if (mesid === 0) return false; // 第 0 层是开场白，右滑只是切换备用开场白，绝不会调用 API
    const ctx = getContext();
    const msg = Number.isFinite(mesid) ? ctx?.chat?.[mesid] : null;
    if (msg && Array.isArray(msg.swipes)) {
      const sid = Number.isFinite(msg.swipe_id) ? msg.swipe_id : 0;
      return sid >= msg.swipes.length - 1;
    }

    const counter = mesEl.querySelector('.swipes-counter');
    if (counter) {
      const m = String(counter.textContent || '').trim().match(/(\d+)\s*\/\s*(\d+)/);
      if (m) return Number(m[1]) >= Number(m[2]);
    }
    return true;
  };

  const onGuardClickCapture = (e) => {
    if (!config.swipeGuard || Date.now() < guardBypassUntil) return;
    const target = e.target;
    if (!target || !target.closest) return;
    if (target.closest('#st-tb-root')) return;

    const regenBtn = target.closest('#option_regenerate, .mes_regenerate, #regenerate_button');
    if (regenBtn) {
      e.preventDefault();
      e.stopImmediatePropagation();
      e.stopPropagation();
      openGuardConfirm(
        '确认重新生成回复？',
        '当前已开启防误触保护，点击确认后才会调用 API 重新生成。',
        () => regenBtn.click()
      );
      return;
    }

    const swipeRightBtn = target.closest('.swipe_right');
    if (swipeRightBtn) {
      const mesEl = swipeRightBtn.closest('.mes');
      if (willSwipeRightGenerate(mesEl)) {
        e.preventDefault();
        e.stopImmediatePropagation();
        e.stopPropagation();
        openGuardConfirm(
          '确认右滑生成新回复？',
          '当前已是最后一条分支，继续右滑将调用 API 生成新内容。',
          () => swipeRightBtn.click()
        );
      }
    }
  };

  const onGuardKeyDownCapture = (e) => {
    if (!config.swipeGuard || Date.now() < guardBypassUntil) return;
    if (e.key !== 'ArrowRight') return;
    const active = doc.activeElement;
    if (active && active.closest && active.closest('input, textarea, select, [contenteditable="true"]')) return;
    const lastMes = doc.querySelector('#chat .mes.last_mes') || doc.querySelector('#chat .mes:last-of-type');
    if (!willSwipeRightGenerate(lastMes)) return;
    const swipeBtn = lastMes?.querySelector('.swipe_right');
    if (!swipeBtn) return;
    e.preventDefault();
    e.stopImmediatePropagation();
    openGuardConfirm(
      '确认右滑生成新回复？',
      '检测到快捷键右滑，当前已是最后一条分支，确认后才调用 API。',
      () => swipeBtn.click()
    );
  };

  const onGuardTouchStartCapture = (e) => {
    if (!config.swipeGuard) return;
    const t = e.touches?.[0];
    if (!t) return;
    const lastMes = e.target?.closest?.('.mes');
    if (!lastMes || !willSwipeRightGenerate(lastMes)) {
      guardTouchStart = null;
      return;
    }
    guardTouchStart = { x: t.clientX, y: t.clientY, mes: lastMes };
  };

  const onGuardTouchEndCapture = (e) => {
    if (e.target && e.target.closest && e.target.closest('#st-tb-root')) { guardTouchStart = null; return; }
    if (!config.swipeGuard || !guardTouchStart || Date.now() < guardBypassUntil) {
      guardTouchStart = null;
      return;
    }
    const t = e.changedTouches?.[0];
    const start = guardTouchStart;
    guardTouchStart = null;
    if (!t) return;
    const dx = t.clientX - start.x;
    const dy = t.clientY - start.y;
    // 手指向左滑动即向右翻页生成新回复
    if (dx < -45 && Math.abs(dx) > Math.abs(dy) * 1.25 && willSwipeRightGenerate(start.mes)) {
      const swipeBtn = start.mes.querySelector('.swipe_right');
      e.preventDefault();
      e.stopImmediatePropagation();
      e.stopPropagation();
      openGuardConfirm(
        '确认滑动生成新回复？',
        '检测到在最后一条消息上滑动刷新，点击确认后才调用 API 生成新内容。',
        () => { if (swipeBtn) swipeBtn.click(); }
      );
    }
  };

  doc.addEventListener('click', onGuardClickCapture, true);
  doc.addEventListener('keydown', onGuardKeyDownCapture, true);
  doc.addEventListener('touchstart', onGuardTouchStartCapture, { capture: true, passive: true });
  doc.addEventListener('touchend', onGuardTouchEndCapture, true);

