  // 首尾含结构助词、方位虚字或语气词的碎片一律剔除（彻底干掉“上的/里的/中的/说了”等）
  const JUNK_EDGE_RE = /^[的地的得着了过上下里中内外前后左右把被向往从给和与跟对为以而却就也都还又再很太更最不没别吗呢吧啊呀哦嘛嗯哈哼哇喂是有这那个些种次回来去到]|([的地的得着了过上下里中内外把被向往从给吗呢吧啊呀哦嘛嗯哈喂])$/;
  const ALL_SAME_CHAR_RE = /^(.)\1+$/;

  const renderChatAnalytics = () => {
    const ctx = getContext();
    const chat = Array.isArray(ctx?.chat) ? ctx.chat : [];
    const mesNodes = Array.from(doc.querySelectorAll('#chat .mes'));

    // 自动收集角色名、用户名、小狗名、群聊发言人名，彻底排除名字及名字切片
    const nameBlockSet = new Set();
    const addBlockedName = (raw) => {
      if (!raw || typeof raw !== 'string') return;
      const cleaned = raw.trim();
      if (!cleaned) return;
      nameBlockSet.add(cleaned.toLowerCase());
      // 中文名字超过 2 字时，将其 2~4 字连续切片也加入屏蔽（如“沈星回”屏蔽“沈星/星回”）
      const zhParts = cleaned.match(/[\u4e00-\u9fa5]{2,}/g) || [];
      for (const zp of zhParts) {
        nameBlockSet.add(zp);
        if (zp.length <= 5) {
          for (let l = 2; l <= zp.length; l++) {
            for (let i = 0; i <= zp.length - l; i++) {
              nameBlockSet.add(zp.slice(i, i + l));
            }
          }
        }
      }
      const enParts = cleaned.toLowerCase().match(/[a-z]{2,}/g) || [];
      enParts.forEach(ep => nameBlockSet.add(ep));
    };
    addBlockedName(ctx?.name1);
    addBlockedName(ctx?.name2);
    addBlockedName(config.puppyOwnerName);
    addBlockedName(config.puppyName);
    for (const mes of mesNodes) {
      addBlockedName(mes.getAttribute('ch_name'));
      const nmEl = mes.querySelector('.name_text');
      if (nmEl) addBlockedName(nmEl.textContent);
    }

    const zhSegmenter = (typeof Intl !== 'undefined' && typeof Intl.Segmenter === 'function')
      ? new Intl.Segmenter('zh-CN', { granularity: 'word' })
      : null;

    let userCount = 0;
    let charCount = 0;
    let charChars = 0;
    let maxLen = 0;
    let maxMesId = 0;
    let visibleCount = 0;
    const daySet = new Set();
    let minDate = null;
    let maxDate = null;
    const freq = new Map();

    for (const mes of mesNodes) {
      if (mes.getAttribute('is_system') === 'true') continue;
      if (isNodeVisuallyHidden(mes)) continue;
      const textEl = mes.querySelector('.mes_text');
      if (!textEl || isNodeVisuallyHidden(textEl)) continue;

      // 仅提取页面肉眼真实呈现出来的正文内容（不包含草稿、隐藏标签或思维链）
      const clean = extractVisibleNodeText(textEl)
        .replace(/\r\n/g, '\n')
        .replace(/[*_`~#>\[\]()]/g, ' ')
        .trim();
      const len = clean.replace(/\s+/g, '').length;
      if (!len) continue;

      visibleCount += 1;
      const mesid = Number(mes.getAttribute('mesid'));
      const isUser = mes.getAttribute('is_user') === 'true';

      if (isUser) {
        userCount += 1;
      } else {
        charCount += 1;
        charChars += len;
      }
      if (len > maxLen) {
        maxLen = len;
        maxMesId = Number.isFinite(mesid) ? mesid : 0;
      }

      const rawMsg = Number.isFinite(mesid) ? chat[mesid] : null;
      if (rawMsg?.send_date) {
        const ts = typeof rawMsg.send_date === 'number' ? rawMsg.send_date : Date.parse(rawMsg.send_date);
        if (Number.isFinite(ts)) {
          const d = new Date(ts);
          const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
          daySet.add(key);
          if (minDate === null || ts < minDate) minDate = ts;
          if (maxDate === null || ts > maxDate) maxDate = ts;
        }
      }

      const recordWord = (w) => {
        if (!w) return;
        const low = w.toLowerCase();
        if (STOP_WORDS.has(w) || STOP_WORDS.has(low)) return;
        if (nameBlockSet.has(w) || nameBlockSet.has(low)) return;
        if (/^[\u4e00-\u9fa5]+$/.test(w)) {
          if (w.length < 2 || w.length > 5) return;
          if (JUNK_EDGE_RE.test(w)) return;
          if (ALL_SAME_CHAR_RE.test(w)) return;
        } else if (/^[a-zA-Z]+$/.test(w)) {
          if (w.length < 4) return;
          w = low;
        } else {
          return;
        }
        freq.set(w, (freq.get(w) || 0) + 1);
      };

      if (zhSegmenter) {
        for (const seg of zhSegmenter.segment(clean)) {
          if (!seg.isWordLike) continue;
          const token = seg.segment.trim();
          if (/^[\u4e00-\u9fa5]{2,5}$/.test(token)) {
            recordWord(token);
          } else if (/^[a-zA-Z]{4,}$/.test(token)) {
            recordWord(token);
          }
        }
      } else {
        // 兼容极老浏览器：按虚词与标点切分完整词块（2~4字），不再强行2字滑窗
        const chunks = clean.split(/[^\u4e00-\u9fa5]+|[的地的得着了过上下里中内外把被向往从给和与跟对为以而却就也都还又再很太更最不没别吗呢吧啊呀哦嘛嗯哈]+/);
        for (const c of chunks) {
          if (c.length >= 2 && c.length <= 4) recordWord(c);
        }
        const enWords = clean.toLowerCase().match(/[a-z]{4,}/g) || [];
        enWords.forEach(recordWord);
      }
    }

    if (!visibleCount) {
      reportBox.innerHTML = '<div class="st-tb-tip" style="margin-top:0;">当前页面暂无可统计的可见正文。</div>';
      reportBox.classList.add('open');
      return;
    }

    const avgCharWords = charCount ? Math.round(charChars / charCount) : 0;
    // 综合真实词频 + 3~4字完整词/成语加成 + 文艺意象词权重进行排序，并去掉被更长词覆盖的碎片
    const scored = Array.from(freq.entries())
      .filter(([, c]) => c >= 2)
      .map(([w, c]) => {
        let weight = c;
        if (/^[\u4e00-\u9fa5]+$/.test(w)) {
          if (w.length === 4) weight *= 1.75;
          else if (w.length === 3) weight *= 1.35;
        }
        if (LITERARY_BOOST_WORDS.has(w)) weight *= 1.65;
        return { w, c, weight };
      })
      .sort((a, b) => b.weight - a.weight || b.c - a.c);

    const topWords = [];
    for (const item of scored) {
      if (topWords.length >= 8) break;
      const isShadowed = topWords.some(([exist]) => exist.length > item.w.length && exist.includes(item.w));
      if (isShadowed) continue;
      topWords.push([item.w, item.c]);
    }

    // 陪伴天数从第一次聊天开始计算（综合该角色所有历史聊天文件名日期、最早消息时间与角色创建/首次对话时间）
    const parseDateStr = (val) => {
      if (!val) return null;
      if (typeof val === 'number' && Number.isFinite(val)) return val;
      const s = String(val);
      const m = s.match(/(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
      if (m) {
        const ts = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])).getTime();
        if (Number.isFinite(ts)) return ts;
      }
      const parsed = Date.parse(s);
      return Number.isFinite(parsed) ? parsed : null;
    };

    let firstChatTs = minDate;
    const considerTs = (ts) => {
      if (Number.isFinite(ts) && ts > 946684800000 && ts <= Date.now() + 86400000) {
        if (firstChatTs === null || ts < firstChatTs) firstChatTs = ts;
      }
    };

    if (Array.isArray(chat)) {
      for (const m of chat) {
        if (m?.send_date) considerTs(parseDateStr(m.send_date));
      }
    }
    if (Array.isArray(chatListCache)) {
      for (const item of chatListCache) {
        considerTs(parseDateStr(item?.file_name));
        considerTs(parseDateStr(item?.last_mes));
      }
    }
    const curChar = getCurrentCharacter();
    if (curChar?.date_added) considerTs(parseDateStr(curChar.date_added));

    let dayInfo = '未记录日期';
    if (firstChatTs !== null) {
      const d0 = new Date(firstChatTs);
      const startDay = new Date(d0.getFullYear(), d0.getMonth(), d0.getDate()).getTime();
      const nowD = new Date();
      const todayDay = new Date(nowD.getFullYear(), nowD.getMonth(), nowD.getDate()).getTime();
      const totalDays = Math.max(1, Math.floor((todayDay - startDay) / 86400000) + 1);
      const startStr = `${d0.getFullYear()}-${String(d0.getMonth() + 1).padStart(2, '0')}-${String(d0.getDate()).padStart(2, '0')}`;
      dayInfo = `已陪伴 ${totalDays} 天 (始于 ${startStr})`;
    }

    reportBox.innerHTML = '';
    const addRow = (k, vNode) => {
      const r = doc.createElement('div');
      r.className = 'st-tb-report-row';
      const s1 = doc.createElement('span');
      s1.textContent = k;
      const s2 = doc.createElement('span');
      if (typeof vNode === 'string') s2.textContent = vNode;
      else s2.appendChild(vNode);
      r.append(s1, s2);
      reportBox.appendChild(r);
    };

    addRow('互动轮次', `你 ${userCount} 条 / 角色 ${charCount} 条`);
    addRow('角色均字', `${avgCharWords} 字`);

    const maxLink = doc.createElement('span');
    maxLink.className = 'st-tb-report-jump';
    maxLink.textContent = `${maxLen} 字 (#${maxMesId})`;
    maxLink.title = '点击跳转到最长楼层';
    maxLink.addEventListener('click', () => {
      scrollAndFlashMes(maxMesId);
      togglePanel(false);
    });
    addRow('单层最长', maxLink);
    addRow('陪伴天数', dayInfo);

    if (topWords.length) {
      const lbl = doc.createElement('div');
      lbl.style.color = 'var(--tb-sub)';
      lbl.style.marginTop = '2px';
      lbl.textContent = '高频词（点击可直接搜索）：';
      reportBox.appendChild(lbl);

      const chips = doc.createElement('div');
      chips.className = 'st-tb-word-chips';
      topWords.forEach(([word, cnt]) => {
        const chip = doc.createElement('button');
        chip.type = 'button';
        chip.className = 'st-tb-chip';
        chip.textContent = `${word} (${cnt})`;
        chip.addEventListener('click', () => {
          searchInput.value = word;
          runSearch(1);
        });
        chips.appendChild(chip);
      });
      reportBox.appendChild(chips);
    }

    reportBox.classList.add('open');
  };

  reportBtn.addEventListener('click', () => {
    if (reportBox.classList.contains('open')) {
      reportBox.classList.remove('open');
      reportBtn.textContent = '查看统计';
    } else {
      renderChatAnalytics();
      reportBtn.textContent = '收起';
    }
  });

  const onMaskClick = (e) => {
    const target = e.target?.closest?.('.st-tb-mask');
    if (!target) return;
    const revealed = target.classList.toggle('revealed');
    if (target.dataset.style === 'custom') {
      runWithoutObserve(() => {
        target.textContent = revealed
          ? (target.dataset.orig ?? '')
          : (target.dataset.masked ?? getCustomMaskDisplay(target.dataset.orig ?? ''));
      });
    }
  };
  doc.addEventListener('click', onMaskClick);

  let maskDebounce = null;
  const scheduleMask = () => {
    if (!config.maskEnabled) return;
    clearTimeout(maskDebounce);
    const sb = doc.getElementById('mes_stop');
    const streaming = sb && !sb.classList.contains('displayNone') && sb.style.display !== 'none';
    maskDebounce = setTimeout(applyMasks, streaming ? 1100 : 320);
  };

  const attachChatObserver = () => {
    const chatEl = doc.getElementById('chat');
    if (!chatEl || chatObserver) return;
    chatObserver = new MutationObserver((mutations) => {
      if (!config.maskEnabled) return;
      const relevant = mutations.some(m =>
        m.addedNodes.length > 0 &&
        !(m.target && m.target.classList && m.target.classList.contains('st-tb-mask'))
      );
      if (relevant) scheduleMask();
    });
    chatObserver.observe(chatEl, { childList: true, subtree: false });
  };

  // ==================== 像素小狗精灵（24x24画布 + 衣服/头饰叠穿 + 小狗币 + 饱食水分心情） ====================
  const getPupPalette = (look = null) => {
    const fur = (look && look.fur) || config.puppyFur || '#fffdf7';
    const ear = (look && look.ear) || config.puppyEar || '#e2ae74';
    const collar = (look && look.collar) || config.puppyCollar || '#d66565';
    const outline = (look && look.outline) || config.puppyOutline || '#3b2a22';
    const showCollar = look ? (look.showCollar !== false) : (config.puppyShowCollar !== false);
    return {
      o: outline,
      w: fur,
      s: shadeHex(fur, 0.89),
      e: ear,
      k: '#231814',
      c: '#6e5244',
      p: '#f59eb0',
      r: showCollar ? collar : fur,
      g: showCollar ? '#f4cf5e' : fur,
    };
  };

