  const CALM_PUP_STATES = new Set(['walk', 'idle', 'sit', 'lie']);
  const markPupSpecialCooldown = (minSec = 13, maxSec = 22) => {
    pup.nextSpecialAt = Date.now() + randInt(minSec * 1000, maxSec * 1000);
  };

  const getTalkFreqGapMs = () => {
    const f = config.puppyTalkFreq || 'normal';
    if (f === 'quiet') return 999999999;
    if (f === 'low') return randInt(150000, 240000);
    if (f === 'chatty') return randInt(18000, 32000);
    return randInt(85000, 145000); // normal: 适中不吵
  };

  let puppyBubbleQueueTimer = null;
  let puppyBubbleFadeTimer = null;
  const puppyBubbleStack = root.querySelector('#st-tb-puppy-bubble-stack');

  const clearBubbleStack = () => {
    clearTimeout(puppyBubbleFadeTimer);
    if (!puppyBubbleStack) return;
    puppyBubbleStack.classList.remove('fade-all');
    puppyBubbleStack.innerHTML = '';
  };

  // Strictly single-line chunks (<= 18 chars) with NO trailing commas/semicolons
  const splitGameBubbles = (str) => {
    const s = String(str || '').trim();
    if (!s) return [];
    const MAX_LINE = 18;

    const splitByPunct = (txt, re) => {
      const out = [];
      let buf = '';
      for (let i = 0; i < txt.length; i++) {
        const ch = txt[i];
        buf += ch;
        if (re.test(ch)) {
          while (i + 1 < txt.length && /[。！？!?~…，,;；—.]/.test(txt[i + 1])) {
            i++;
            buf += txt[i];
          }
          const t = buf.trim();
          if (t) out.push(t);
          buf = '';
        }
      }
      if (buf.trim()) out.push(buf.trim());
      return out;
    };

    const sentences = splitByPunct(s, /[。！？!?~]/);
    const clauses = [];
    for (const sent of sentences) {
      if (sent.length <= MAX_LINE) {
        clauses.push(sent);
        continue;
      }
      const sub = splitByPunct(sent, /[，,;；—…]/);
      for (const piece of sub) {
        if (piece.length <= MAX_LINE) {
          clauses.push(piece);
        } else {
          const n = Math.ceil(piece.length / MAX_LINE);
          const step = Math.ceil(piece.length / n);
          for (let k = 0; k < piece.length; k += step) {
            const part = piece.slice(k, k + step).trim();
            if (part) clauses.push(part);
          }
        }
      }
    }

    const packed = [];
    for (const c of clauses) {
      if (!c) continue;
      if (packed.length > 0 && (packed[packed.length - 1].length + c.length) <= MAX_LINE && !/[。！？!?~]$/.test(packed[packed.length - 1])) {
        packed[packed.length - 1] += c;
      } else if (packed.length > 0 && c.length <= 4 && (packed[packed.length - 1].length + c.length) <= MAX_LINE + 2) {
        packed[packed.length - 1] += c;
      } else {
        packed.push(c);
      }
    }
    // Strip trailing commas/semicolons/pauses so split bubbles look clean and crisp
    return packed
      .map(seg => seg.replace(/[，,;；、]+$/g, '').trim())
      .filter(Boolean);
  };

  const promoteCurrentBubbleToStack = () => {
    if (!puppyBubbleStack || !puppyBubble.classList.contains('show')) return;
    const bTxt = puppyBubble.querySelector('#st-tb-puppy-bubble-txt');
    const prevText = (bTxt ? bTxt.textContent : puppyBubble.textContent || '').trim();
    if (!prevText) return;
    const cs = win.getComputedStyle(puppyBubble);
    const pill = doc.createElement('div');
    pill.className = 'st-bub-prev';
    pill.textContent = prevText;
    pill.style.background = cs.background;
    pill.style.border = cs.border;
    pill.style.color = cs.color;
    pill.style.boxShadow = cs.boxShadow;
    pill.style.fontFamily = cs.fontFamily;
    pill.style.fontSize = cs.fontSize;
    pill.style.fontWeight = cs.fontWeight;
    pill.style.letterSpacing = cs.letterSpacing;
    pill.style.padding = cs.padding;
    pill.style.borderRadius = cs.borderRadius;
    puppyBubbleStack.classList.remove('fade-all');
    puppyBubbleStack.appendChild(pill);
    const pills = Array.from(puppyBubbleStack.children).filter(el => !el.classList.contains('fade-out'));
    while (pills.length > 2) {
      const oldest = pills.shift();
      oldest.classList.add('fade-out');
      setTimeout(() => { if (oldest.parentNode) oldest.remove(); }, 260);
    }
  };

  const clampBubbleToViewport = () => {
    puppyBubble.style.marginLeft = '0px';
    puppyBubble.style.width = '';
    puppyBubble.style.setProperty('--tail-x', '50%');
    if (puppyBubbleStack) puppyBubbleStack.style.marginLeft = '0px';
    win.requestAnimationFrame(() => {
      if (!puppyBubble.classList.contains('show')) return;
      // 换行模式下精确收紧气泡宽度到最长一行文字宽度，确保左右边距完全对称
      if (!puppyBubble.classList.contains('is-split-mode')) {
        const bTxt = puppyBubble.querySelector('#st-tb-puppy-bubble-txt');
        if (bTxt && bTxt.firstChild && typeof doc.createRange === 'function') {
          try {
            const rng = doc.createRange();
            rng.selectNodeContents(bTxt);
            const rects = Array.from(rng.getClientRects());
            if (rects.length > 1) {
              let maxLineW = 0;
              for (const r of rects) if (r.width > maxLineW) maxLineW = r.width;
              if (maxLineW > 20) {
                const cs = win.getComputedStyle(puppyBubble);
                const padX = (parseFloat(cs.paddingLeft) || 10) + (parseFloat(cs.paddingRight) || 10);
                const bdX = (parseFloat(cs.borderLeftWidth) || 2) + (parseFloat(cs.borderRightWidth) || 2);
                puppyBubble.style.width = `${Math.ceil(maxLineW + padX + bdX + 1)}px`;
              }
            }
          } catch (_) {}
        }
      }
      const rect = puppyBubble.getBoundingClientRect();
      let shift = 0;
      if (rect.left < 8) shift = 8 - rect.left;
      else if (rect.right > win.innerWidth - 8) shift = (win.innerWidth - 8) - rect.right;
      if (shift !== 0) {
        puppyBubble.style.marginLeft = `${Math.round(shift)}px`;
        const tailPx = Math.round(clamp(rect.width / 2 - shift, 10, Math.max(10, rect.width - 10)));
        puppyBubble.style.setProperty('--tail-x', `${tailPx}px`);
      }
      if (puppyBubbleStack && puppyBubbleStack.children.length > 0) {
        const bottomPx = 74 + Math.max(24, puppyBubble.offsetHeight) + 6;
        puppyBubbleStack.style.bottom = `${bottomPx}px`;
        const sRect = puppyBubbleStack.getBoundingClientRect();
        let sShift = 0;
        if (sRect.left < 8) sShift = 8 - sRect.left;
        else if (sRect.right > win.innerWidth - 8) sShift = (win.innerWidth - 8) - sRect.right;
        if (sShift !== 0) puppyBubbleStack.style.marginLeft = `${Math.round(sShift)}px`;
      }
      if (activeBubDynMode) {
        const bf = root.querySelector('#st-tb-bub-fx');
        if (bf) {
          const tw = Math.max(48, Math.round((puppyBubble.offsetWidth + 20) / 2));
          const th = Math.max(24, Math.round((puppyBubble.offsetHeight + 20) / 2));
          if (bf.width !== tw || bf.height !== th) { bf.width = tw; bf.height = th; }
        }
      }
    });
  };

  const showPuppyBubble = (text, duration = 1800, isAuto = false) => {
    const now = Date.now();
    if (isAuto) {
      if ((config.puppyTalkFreq || 'normal') === 'quiet') return;
      if (now < pup.nextAutoBubbleAt || puppyBubble.classList.contains('show')) return;
    }
    const cleanText = typeof applyGenderText === 'function' ? applyGenderText(String(text || '')) : String(text || '');
    clearTimeout(puppyBubbleTimer);
    clearTimeout(puppyBubbleQueueTimer);
    clearBubbleStack();

    const mode = config.puppyBubbleMode || 'wrap';
    const isSplit = mode === 'split';
    puppyBubble.classList.toggle('is-split-mode', isSplit);
    const chunks = isSplit ? splitGameBubbles(cleanText) : [cleanText];
    if (!chunks.length) return;

    const showChunk = (idx) => {
      if (idx > 0) {
        promoteCurrentBubbleToStack();
      }
      const seg = chunks[idx];
      const bTxt = puppyBubble.querySelector('#st-tb-puppy-bubble-txt');
      if (bTxt) bTxt.textContent = seg;
      else puppyBubble.textContent = seg;
      puppyBubble.classList.remove('pop-in');
      void puppyBubble.offsetWidth;
      puppyBubble.classList.add('show', 'pop-in');
      clampBubbleToViewport();

      if (idx + 1 < chunks.length) {
        const stepDelay = Math.max(1350, Math.min(2200, seg.length * 85 + 520));
        puppyBubbleQueueTimer = setTimeout(() => showChunk(idx + 1), stepDelay);
      } else {
        const holdDur = chunks.length > 1
          ? Math.max(3800, Math.min(5600, seg.length * 105 + 1800))
          : Math.max(duration, seg.length > 20 ? Math.min(5400, seg.length * 100 + 1200) : duration);
        puppyBubbleTimer = setTimeout(() => {
          puppyBubble.classList.remove('show', 'pop-in');
          if (puppyBubbleStack && puppyBubbleStack.children.length > 0) {
            puppyBubbleStack.classList.add('fade-all');
            puppyBubbleFadeTimer = setTimeout(clearBubbleStack, 280);
          }
        }, holdDur);
      }
    };

    const totalDur = chunks.length > 1
      ? chunks.slice(0, -1).reduce((acc, s) => acc + Math.max(1350, Math.min(2200, s.length * 85 + 520)), 0)
        + Math.max(3800, Math.min(5600, chunks[chunks.length - 1].length * 105 + 1800))
      : Math.max(duration, cleanText.length > 20 ? Math.min(5400, cleanText.length * 100 + 1200) : duration);

    pup.nextAutoBubbleAt = now + totalDur + (isAuto ? getTalkFreqGapMs() : randInt(12000, 20000));
    if (pup.state !== 'lie') pup.nextLieAt = Math.max(pup.nextLieAt || 0, now + 36000);
    showChunk(0);
  };

  const spawnPupFx = (kind, x, y) => {
    if (pup.fxParticles.length > 16) pup.fxParticles.shift();
    // 让小狗头顶飘出的小装饰随机丰富（爱心/星光/小花/四叶草/音符自然轮换）
    const fxPool = ['heart', 'sparkle', 'flower_fx', 'clover_fx', 'note'];
    const actualKind = (kind === 'heart' || kind === 'note' || kind === 'sparkle') && Math.random() < 0.72 ? pick(fxPool) : kind;
    pup.fxParticles.push({
      kind: actualKind,
      x,
      y,
      vx: (Math.random() - 0.5) * 0.25,
      vy: -(0.18 + Math.random() * 0.16),
      life: 28 + Math.floor(Math.random() * 14),
      phase: Math.random() * Math.PI * 2,
      color: kind === 'heart'
        ? pick(['#f26b8a', '#ff85a1', '#e64d72'])
        : kind === 'sparkle'
          ? pick(['#ffe066', '#ffd24c', '#a8e0ff'])
          : kind === 'flower_fx'
            ? pick(['#ff9eb5', '#ffd4e0', '#b8d8ff', '#ffe49e'])
            : kind === 'clover_fx'
              ? pick(['#7ac46a', '#8cd67c'])
              : kind === 'note'
                ? pick(['#5c8ee6', '#e88b5a', '#64b882'])
                : '#e34848',
    });
  };

  const getPupName = () => String(config.puppyName || '小狗').trim() || '小狗';
  const getPupSelfName = () => String(config.puppySelfName || '').trim() || getPupName();
  const getOwnerTitle = () => String(config.puppyOwnerTitle || '').trim() || '你';

  const getAffinityInfo = () => {
    const pts = Math.max(0, Math.floor(config.puppyAffinity || 0));
    let cur = AFFINITY_LEVELS[0];
    let next = AFFINITY_LEVELS[1];
    for (let i = 0; i < AFFINITY_LEVELS.length; i++) {
      if (pts >= AFFINITY_LEVELS[i].min) {
        cur = AFFINITY_LEVELS[i];
        next = AFFINITY_LEVELS[i + 1] || null;
      }
    }
    const pct = next ? clamp(Math.round(((pts - cur.min) / (next.min - cur.min)) * 100), 0, 100) : 100;
    return { pts, lv: cur.lv, name: cur.name, pct };
  };

