  const makeGoodsIconCanvas = (id, small = false) => {
    const c = doc.createElement('canvas');
    c.width = 11; c.height = 11;
    c.className = small ? 'st-px-goods-ico-sm' : 'st-px-goods-ico';
    const g = c.getContext('2d');
    const grid = GOODS_ICO_GRIDS[id] || GOODS_ICO_GRIDS.snack_cake;
    for (let y = 0; y < grid.length; y++) {
      for (let x = 0; x < grid[y].length; x++) {
        const col = GOODS_ICO_PAL[grid[y][x]];
        if (col) { g.fillStyle = col; g.fillRect(x, y, 1, 1); }
      }
    }
    return c;
  };

