  const makeAchOrnCanvas = (frameKey, side) => {
    const c = doc.createElement('canvas');
    c.width = 7;
    c.height = 9;
    c.className = `st-px-ach-orn ${side}`;
    const g = c.getContext('2d');
    const grid = ACH_ORN_GRIDS[frameKey] || ACH_ORN_GRIDS.stars;
    for (let y = 0; y < grid.length; y++) {
      for (let x = 0; x < grid[y].length; x++) {
        const col = ACH_ICON_PAL[grid[y][x]];
        if (col) { g.fillStyle = col; g.fillRect(x, y, 1, 1); }
      }
    }
    return c;
  };

  const makeAchIconCanvas = (iconKey) => {
    const c = doc.createElement('canvas');
    c.width = 9;
    c.height = 9;
    c.className = 'st-px-ach-ico';
    const g = c.getContext('2d');
    const grid = ACH_ICON_GRIDS[iconKey] || ACH_ICON_GRIDS.tag;
    let minY = 9, maxY = -1, minX = 9, maxX = -1;
    for (let y = 0; y < grid.length; y++) {
      for (let x = 0; x < grid[y].length; x++) {
        if (ACH_ICON_PAL[grid[y][x]]) {
          if (y < minY) minY = y; if (y > maxY) maxY = y;
          if (x < minX) minX = x; if (x > maxX) maxX = x;
        }
      }
    }
    const offY = maxY >= minY ? Math.floor((9 - (maxY - minY + 1)) / 2) - minY : 0;
    const offX = maxX >= minX ? Math.floor((9 - (maxX - minX + 1)) / 2) - minX : 0;
    for (let y = 0; y < grid.length; y++) {
      for (let x = 0; x < grid[y].length; x++) {
        const col = ACH_ICON_PAL[grid[y][x]];
        if (col) { g.fillStyle = col; g.fillRect(x + offX, y + offY, 1, 1); }
      }
    }
    return c;
  };

