  let achFilterMode = 'all';
  let achCatFilter = 'all'; // 'all' | 'unlocked' | 'locked'

  const renderPupAchievements = () => {
    if (!achListEl) return;
    const unlockedSet = new Set(config.puppyUnlockedTitles || []);
    if (!config.puppyAchClues || typeof config.puppyAchClues !== 'object') config.puppyAchClues = {};
    if (achHeadEl) achHeadEl.innerHTML = `成就称号 (${unlockedSet.size}/${PUP_ACHIEVEMENTS.length})${freshNewAchs.size > 0 ? '<span class="st-px-new-tag">NEW</span>' : ''}`;
    achListEl.innerHTML = '';

    // 顶部分类筛选条：全部 / 已获得 / 未获得
    const filterBar = doc.createElement('div');
    filterBar.style.cssText = 'display:flex;gap:4px;margin-bottom:6px;';
    const unCnt = unlockedSet.size;
    const lkCnt = PUP_ACHIEVEMENTS.length - unCnt;
    [
      { id: 'all', lbl: `全部 (${PUP_ACHIEVEMENTS.length})` },
      { id: 'unlocked', lbl: `已获得 (${unCnt})` },
      { id: 'locked', lbl: `未获得 (${lkCnt})` },
    ].forEach(f => {
      const fb = doc.createElement('button');
      fb.type = 'button';
      fb.className = `st-px-btn${achFilterMode === f.id ? ' active care' : ''}`;
      fb.style.cssText = 'flex:1;height:22px;font-size:9px;padding:0 4px;';
      fb.textContent = f.lbl;
      fb.addEventListener('click', () => {
        achFilterMode = f.id;
        renderPupAchievements();
      });
      filterBar.appendChild(fb);
    });
    achListEl.appendChild(filterBar);

    // 分类筛选条：全部类型 / 各单独分类（不用反复上下滑动）
    const catBar = doc.createElement('div');
    catBar.style.cssText = 'display:flex;flex-wrap:wrap;gap:3px;margin-bottom:6px;';
    const catDefs = [
      { key: 'all', lbl: '全部类型' },
      { key: 'bond', lbl: '陪伴' },
      { key: 'wardrobe', lbl: '衣橱' },
      { key: 'daily', lbl: '日常' },
      { key: 'adv', lbl: '冒险' },
      { key: 'game', lbl: '游乐' },
      { key: 'checkin', lbl: '签到' },
      { key: 'hidden', lbl: '隐藏' },
    ];
    catDefs.forEach(cd => {
      const cb = doc.createElement('button');
      cb.type = 'button';
      cb.className = `st-px-btn${achCatFilter === cd.key ? ' active care' : ''}`;
      cb.style.cssText = 'height:20px;font-size:9px;padding:0 6px;flex:0 0 auto;';
      cb.textContent = cd.lbl;
      cb.addEventListener('click', () => {
        achCatFilter = cd.key;
        renderPupAchievements();
      });
      catBar.appendChild(cb);
    });
    achListEl.appendChild(catBar);

    const achById = new Map(PUP_ACHIEVEMENTS.map(a => [a.id, a]));
    const placed = new Set();
    const groupsToRender = ACH_GROUPS.map(g => {
      const items = [];
      if (g.key === 'hidden') {
        PUP_ACHIEVEMENTS.forEach(a => { if (a.hidden && !placed.has(a.id)) { items.push(a); placed.add(a.id); } });
      } else {
        g.ids.forEach(id => {
          const a = achById.get(id);
          if (a && !a.hidden && !placed.has(a.id)) { items.push(a); placed.add(a.id); }
        });
      }
      return { key: g.key, name: g.name, items };
    });
    // 未显式归类的普通成就自动并入“日常”而非另起“其他趣味成就”，且永远在隐藏成就前面
    const leftover = PUP_ACHIEVEMENTS.filter(a => !placed.has(a.id));
    if (leftover.length) {
      const dailyGrp = groupsToRender.find(x => x.key === 'daily') || groupsToRender[0];
      if (dailyGrp) dailyGrp.items.push(...leftover);
    }

    let renderedAny = false;
    groupsToRender.forEach(grp => {
      if (achCatFilter !== 'all' && grp.key !== achCatFilter) return;
      const filtered = grp.items.filter(ach => {
        const u = unlockedSet.has(ach.id);
        if (achFilterMode === 'unlocked') return u;
        if (achFilterMode === 'locked') return !u;
        return true;
      });
      if (!filtered.length) return;
      renderedAny = true;

      const gHead = doc.createElement('div');
      gHead.style.cssText = 'font-size:9px;font-weight:700;color:var(--px-fg,#6b4852);padding:3px 2px 2px;margin-top:3px;border-bottom:1px dashed var(--px-border,#bfa4ae);';
      const gGot = grp.items.filter(a => unlockedSet.has(a.id)).length;
      gHead.textContent = `${grp.name} (${gGot}/${grp.items.length})`;
      achListEl.appendChild(gHead);

      filtered.forEach(ach => {
        const unlocked = unlockedSet.has(ach.id);
        const isMystery = Boolean(ach.hidden && !unlocked);
        const wearing = config.puppyActiveTitle === ach.id;
        const clueLv = Number(config.puppyAchClues[ach.id] || 0);
        const row = doc.createElement('div');
        row.className = `st-px-ach-item${unlocked ? '' : ' locked'}${wearing ? ' wearing' : ''}`;
        row.style.flexDirection = 'column';
        row.style.alignItems = 'stretch';

        const topWrap = doc.createElement('div');
        topWrap.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:6px;';
        const info = doc.createElement('div');
        info.style.flex = '1';
        const topLine = doc.createElement('div');
        topLine.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap;';

        const pill = doc.createElement('span');
        fillAchBadgeEl(pill, ach, isMystery);

        const rewSpan = doc.createElement('span');
        rewSpan.style.fontWeight = '700';
        rewSpan.textContent = `+${ach.reward}币`;
        if (freshNewAchs.has(ach.id)) {
          const nTag = doc.createElement('span');
          nTag.className = 'st-px-new-tag';
          nTag.textContent = 'NEW';
          topLine.append(pill, nTag, rewSpan);
        } else {
          topLine.append(pill, rewSpan);
        }

        const descDiv = doc.createElement('div');
        descDiv.style.cssText = 'font-size:9px;opacity:0.88;margin-top:3px;line-height:1.4;';
        if (!isMystery) {
          descDiv.textContent = ach.desc;
        } else {
          const cPair = HIDDEN_ACH_CLUES[ach.id] || ['试着在日常里多探索一些意想不到的互动', '仔细翻翻背包、衣橱、花盆或扭蛋的隐藏彩蛋'];
          if (clueLv >= 3) descDiv.textContent = `[已揭秘] ${ach.desc}`;
          else if (clueLv === 2) descDiv.textContent = `[具体线索] ${cPair[1]}`;
          else if (clueLv === 1) descDiv.textContent = `[模糊线索] ${cPair[0]}`;
          else descDiv.textContent = '神秘隐藏成就，可花小狗币购买线索提示';
        }
        info.append(topLine, descDiv);

        const btn = doc.createElement('button');
        btn.type = 'button';
        btn.className = 'st-px-btn';
        btn.style.cssText = 'height:22px;padding:0 7px;font-size:9px;flex-shrink:0;';
        btn.disabled = !unlocked;
        btn.textContent = !unlocked ? '未解锁' : (wearing ? '卸下' : '佩戴');
        btn.addEventListener('click', () => {
          if (!unlocked) return;
          freshNewAchs.delete(ach.id);
          config.puppyActiveTitle = wearing ? '' : ach.id;
          saveConfig();
          updatePupStatBars();
          renderPupAchievements();
        });
        topWrap.append(info, btn);
        row.appendChild(topWrap);

        // 未解锁的隐藏成就：提供 2币模糊 / 5币具体 / 10币直接揭秘 线索购买（每次必弹窗确认！）
        if (isMystery && clueLv < 3) {
          const clueRow = doc.createElement('div');
          clueRow.style.cssText = 'display:flex;gap:4px;margin-top:4px;flex-wrap:wrap;';
          [
            { lv: 1, cost: 2, label: '模糊线索 2币' },
            { lv: 2, cost: 5, label: '具体线索 5币' },
            { lv: 3, cost: 10, label: '直接揭秘 10币' },
          ].filter(c => c.lv > clueLv).forEach(c => {
            const cb = doc.createElement('button');
            cb.type = 'button';
            cb.className = 'st-px-btn';
            cb.style.cssText = 'height:20px;padding:0 6px;font-size:9px;';
            cb.textContent = c.label;
            cb.addEventListener('click', () => {
              const curCoins = Math.max(0, Math.floor(config.puppyCoins || 0));
              if (curCoins < c.cost) {
                showPuppyBubble(`小狗币不够 ${c.cost} 枚啦，再去打工或玩游戏攒一点吧~`, 2000);
                return;
              }
              openGuardConfirm(
                `确认购买【${c.label}】？`,
                `将花费 ${c.cost} 枚小狗币（当前余额 ${curCoins} 币），解锁这条隐藏成就的提示。`,
                () => {
                  const nowC = Math.max(0, Math.floor(config.puppyCoins || 0));
                  if (nowC < c.cost) return;
                  config.puppyCoins = nowC - c.cost;
                  config.puppyAchClues = config.puppyAchClues || {};
                  config.puppyAchClues[ach.id] = c.lv;
                  saveConfig();
                  updatePupStatBars();
                  renderPupAchievements();
                  showPuppyBubble(c.lv === 3 ? '隐藏成就获取方法已揭秘!' : '收到新线索啦，快看看提示吧~', 2200);
                },
                '确认购买',
                true
              );
            });
            clueRow.appendChild(cb);
          });
          row.appendChild(clueRow);
        }

        achListEl.appendChild(row);
      });
    });

    if (!renderedAny) {
      const empty = doc.createElement('div');
      empty.style.cssText = 'font-size:10px;color:#8c747e;text-align:center;padding:12px 0;';
      empty.textContent = achFilterMode === 'unlocked' ? '还没有已获得的成就哦，快去和小狗互动吧~' : '哇，所有成就都已经集齐啦!';
      achListEl.appendChild(empty);
    }
  };

  const parseBirthdayMmdd = (val) => {
    const s = String(val || '').trim();
    if (!s) return '';
    const m1 = s.match(/(\d{1,2})\s*[-/.月]\s*(\d{1,2})/);
    if (m1) return `${String(Number(m1[1])).padStart(2, '0')}-${String(Number(m1[2])).padStart(2, '0')}`;
    return '';
  };

