  const getPersTalk = (cat, val = '') => {
    const curP = config.puppyPersonality || 'sleepyhead';
    const bank = PUP_TALK_BY_PERS[curP] || PUP_TALK_BY_PERS.sleepyhead;
    const arr = bank[cat] || PUP_TALK_BY_PERS.sleepyhead[cat] || ['汪~'];
    return formatPupText(pick(arr)).replace(/\{item\}/g, String(val)).replace(/\{lack\}/g, String(val));
  };

  const getPersIdle = (kind) => {
    const curP = config.puppyPersonality || 'sleepyhead';
    const bank = PUP_IDLE_BY_PERS[curP] || PUP_IDLE_BY_PERS.sleepyhead;
    const arr = bank[kind] || PUP_IDLE_BY_PERS.sleepyhead[kind] || ['汪~'];
    return formatPupText(pick(arr));
  };

  const getPersReact = (kind) => {
    const curP = config.puppyPersonality || 'sleepyhead';
    const bank = PUP_INTERACT_BY_PERS[curP] || PUP_INTERACT_BY_PERS.sleepyhead;
    const arr = bank[kind] || PUP_INTERACT_BY_PERS.sleepyhead[kind] || ['汪~'];
    return formatPupText(pick(arr));
  };

  const handleSinglePuppyTap = () => {
    const now = Date.now();
    if (pup.state === 'sleep') {
      config.puppyStats.wokePup = true;
      checkPupAchievements();
      if (Math.random() < 0.5) {
        setPuppyState('shock', 75);
        showPuppyBubble(getPersReact('wakeShock'), 1900);
      } else {
        setPuppyState('angry', 90);
        showPuppyBubble(getPersReact('wakeAngry'), 1900);
      }
      return;
    }

    if (now > pup.annoyResetAt) pup.annoyCount = 0;
    pup.annoyCount += 1;
    pup.annoyResetAt = now + 4500;

    if (pup.annoyCount >= 5) {
      pup.dir *= -1;
      setPuppyState('angry', 110);
      adjustPupStats(0, 0, -5);
      showPuppyBubble(getPersReact('annoy5'), 2100);
      return;
    }
    if (pup.annoyCount >= 3) {
      setPuppyState('speechless', 90);
      config.puppyStats = config.puppyStats || {}; config.puppyStats.pokeAnnoyCount = (config.puppyStats.pokeAnnoyCount || 0) + 1; scheduleSaveConfig(); checkPupAchievements();
      showPuppyBubble(getPersReact('annoy3'), 1900);
      return;
    }

    // 饿了或渴了时点击会先哼唧撒娇
    if (config.puppyHunger < 25) {
      setPuppyState('sad', 90);
      showPuppyBubble(getPersReact('hungry'), 2100);
      return;
    }
    if (config.puppyThirst < 25) {
      setPuppyState('sad', 90);
      showPuppyBubble(getPersReact('thirsty'), 2100);
      return;
    }

    // 丰富的单击互动反应（摸头/蹦跶/转圈/伸懒腰）+ 好感 + 概率掉小狗币
    adjustPupStats(0, 0, 5);
    config.puppyStats.pets = (config.puppyStats.pets || 0) + 1;
    addPupAffinity(1, 'pet');
    const roll = Math.random();
    let msg = '';
    if (roll < 0.55) {
      setPuppyState('happy', 85);
      msg = getPersReact('tapHappy');
    } else if (roll < 0.75) {
      setPuppyState('bounce', 80);
      msg = getPersReact('tapPlay');
    } else if (roll < 0.9) {
      setPuppyState('spin', 75);
      msg = getPersReact('tapPlay');
    } else {
      setPuppyState('stretch', 80);
      msg = getPersReact('tapStretch');
    }

    markPupSpecialCooldown(12, 18);
    const coins = tryDropPupCoins(0.15, 1, 2, false, true);
    if (coins > 0) {
      const usedToday = getClickCoinDaily().count || 0;
      showPuppyBubble(`${msg} (+${coins}币 今日${usedToday}/5)`, 2200);
    } else {
      showPuppyBubble(msg, 1600);
    }
  };

  let pupDragSuppressUntil = 0;
