  const ensureDailyWishlist = () => {
    const today = new Date().toISOString().slice(0, 10);
    if (!config.puppyWishlist || typeof config.puppyWishlist !== 'object') {
      config.puppyWishlist = { date: '', items: [], allClaimed: false, totalDone: 0 };
    }
    const wl = config.puppyWishlist;
    if (wl.date !== today || !Array.isArray(wl.items) || wl.items.length === 0) {
      const pool = WISH_POOL.slice();
      for (let i = pool.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [pool[i], pool[j]] = [pool[j], pool[i]];
      }
      wl.date = today;
      wl.allClaimed = false;
      wl.items = pool.slice(0, 3).map(w => ({
        id: w.id, title: w.title, desc: w.desc,
        target: w.target, prog: 0, coins: w.coins, aff: w.aff, claimed: false,
      }));
      scheduleSaveConfig();
    }
    return wl;
  };

  const updateWishTabBadge = () => {
    const btn = root.querySelector('#st-px-act-wish-btn');
    if (!btn) return;
    const wl = ensureDailyWishlist();
    const ready = wl.items.filter(w => !w.claimed && w.prog >= w.target).length;
    btn.textContent = ready > 0 ? `心愿(${ready})` : '心愿';
  };

  const progressPupWish = (wishId, delta = 1) => {
    const wl = ensureDailyWishlist();
    let changed = false;
    wl.items.forEach(w => {
      if (w.id === wishId && !w.claimed && w.prog < w.target) {
        w.prog = Math.min(w.target, (w.prog || 0) + delta);
        changed = true;
      }
    });
    if (changed) {
      scheduleSaveConfig();
      updateWishTabBadge();
      if (pupBagOpen && pupBagTab === 'act' && actSubTab === 'wish') renderWishlist();
    }
  };

  const renderWishlist = () => {
    const listEl = root.querySelector('#st-px-wish-list');
    const statEl = root.querySelector('#st-px-wish-stat');
    const bonusBtn = root.querySelector('#st-px-wish-bonus-btn');
    if (!listEl) return;
    const wl = ensureDailyWishlist();
    const doneCnt = wl.items.filter(w => w.claimed).length;
    if (statEl) statEl.textContent = `今日 ${doneCnt}/${wl.items.length} · 累计 ${wl.totalDone || 0}`;
    listEl.innerHTML = '';
    wl.items.forEach(w => {
      const card = doc.createElement('div');
      card.className = 'st-px-adv-card';
      card.style.cssText = 'margin:0;padding:6px 8px;display:flex;align-items:center;justify-content:space-between;gap:6px;';
      const left = doc.createElement('div');
      left.style.cssText = 'flex:1;min-width:0;';
      const t = doc.createElement('div');
      t.style.cssText = 'font-size:11px;font-weight:700;color:#3b2a22;';
      t.textContent = `${w.title} (${Math.min(w.prog || 0, w.target)}/${w.target})`;
      const d = doc.createElement('div');
      d.style.cssText = 'font-size:9px;color:#6b5446;margin-top:2px;';
      d.textContent = `${w.desc} · 奖励 +${w.coins}币 / +${w.aff}好感`;
      left.append(t, d);
      const btn = doc.createElement('button');
      btn.type = 'button';
      btn.className = 'st-px-btn' + (!w.claimed && w.prog >= w.target ? ' care' : '');
      btn.style.cssText = 'height:24px;padding:0 8px;font-size:10px;white-space:nowrap;';
      if (w.claimed) {
        btn.textContent = '已领取';
        btn.disabled = true;
        btn.style.opacity = '0.55';
      } else if (w.prog >= w.target) {
        btn.textContent = '领奖励';
        btn.addEventListener('click', () => {
          w.claimed = true;
          wl.totalDone = (wl.totalDone || 0) + 1;
          config.puppyCoins = Math.max(0, Math.floor(config.puppyCoins || 0)) + w.coins;
          config.puppyStats.coinsEarned = (config.puppyStats.coinsEarned || 0) + w.coins;
          addPupAffinity(w.aff, 'wish');
          adjustPupStats(0, 0, 8);
          saveConfig();
          updatePupStatBars();
          checkPupAchievements();
          updateWishTabBadge();
          renderWishlist();
          if (config.puppyEnabled) {
            setPuppyState('happy', 100);
            showPuppyBubble(pickPersLine(WISH_THANK_BY_PERS) + ` (+${w.coins}币)`, 2800);
          }
        });
      } else {
        btn.textContent = '进行中';
        btn.disabled = true;
        btn.style.opacity = '0.6';
      }
      card.append(left, btn);
      listEl.appendChild(card);
    });
    if (bonusBtn) {
      const allDone = wl.items.length > 0 && wl.items.every(w => w.claimed);
      if (allDone && !wl.allClaimed) {
        bonusBtn.style.display = 'block';
        bonusBtn.disabled = false;
        bonusBtn.textContent = '领取今日全达成额外奖励 (+5币 / +3好感)';
      } else if (wl.allClaimed) {
        bonusBtn.style.display = 'block';
        bonusBtn.disabled = true;
        bonusBtn.textContent = '今日心愿已全部圆满达成';
      } else {
        bonusBtn.style.display = 'none';
      }
    }
    updateWishTabBadge();
  };

  const wishBonusBtn = root.querySelector('#st-px-wish-bonus-btn');


  const persFoldBtn = root.querySelector('#st-px-pers-fold');
  const persFoldBox = root.querySelector('#st-px-pers-box');
  if (persFoldBtn && persFoldBox) {
    persFoldBtn.addEventListener('click', () => {
      const isOpen = persFoldBox.style.display !== 'none';
      persFoldBox.style.display = isOpen ? 'none' : 'block';
      persFoldBtn.textContent = isOpen ? '展开' : '收起';
    });
  }

  const renderGenderAndBubbleSettings = () => {
    const headEl = root.querySelector('#st-tb-gender-head');
    const boxEl = root.querySelector('#st-tb-gender-box');
    const bubBtn = root.querySelector('#st-tb-pup-bub-mode');
    if (bubBtn) {
      const m = config.puppyBubbleMode || 'wrap';
      bubBtn.textContent = m === 'split' ? '分段气泡' : '适宽换行';
      bubBtn.title = m === 'split'
        ? '每个气泡单行显示，上一句会上浮保留片刻，下一句紧接弹出'
        : '长句子按适中宽度自动换行，避免超出屏幕';
    }
    if (!boxEl || !headEl) return;
    const g = config.puppyGender || '';
    const gLabel = g === 'boy' ? '小男孩' : (g === 'girl' ? '小女孩' : '未设定');
    headEl.textContent = `小狗性别：${gLabel}`;
    boxEl.innerHTML = '';
    if (!config.puppyGenderLocked) {
      const mk = (val, txt) => {
        const b = doc.createElement('button');
        b.type = 'button';
        b.className = 'st-px-btn care';
        b.style.cssText = 'flex:1;height:24px;font-size:10px;';
        b.textContent = txt;
        b.addEventListener('click', () => {
          config.puppyGender = val;
          config.puppyGenderLocked = true;
          saveConfig();
          renderGenderAndBubbleSettings();
          if (config.puppyEnabled) {
            setPuppyState('happy', 100);
            showPuppyBubble(getPersExtra(val === 'boy' ? 'genderSetBoy' : 'genderSetGirl'), 2800);
          }
        });
        return b;
      };
      boxEl.append(mk('boy', '设为小男孩 (免费选一次)'), mk('girl', '设为小女孩 (免费选一次)'));
    } else {
      const pots = Math.max(0, Math.floor(config.puppyInventory?.gender_potion || 0));
      const nextVal = g === 'boy' ? 'girl' : 'boy';
      const nextTxt = nextVal === 'boy' ? '小男孩' : '小女孩';
      const b = doc.createElement('button');
      b.type = 'button';
      b.className = 'st-px-btn' + (pots > 0 ? ' care' : '');
      b.style.cssText = 'width:100%;height:24px;font-size:10px;';
      b.disabled = pots <= 0;
      if (pots <= 0) b.style.opacity = '0.6';
      b.textContent = pots > 0 ? `喝性别转换药水改为${nextTxt} (余${pots})` : '已定型，需去商城买「性别转换药水」才可更改';
      b.addEventListener('click', () => {
        if ((config.puppyInventory?.gender_potion || 0) <= 0) return;
        config.puppyInventory.gender_potion -= 1;
        if (config.puppyInventory.gender_potion <= 0) delete config.puppyInventory.gender_potion;
        config.puppyGender = nextVal;
        config.puppyStats = config.puppyStats || {};
        config.puppyStats.genderSwitched = true;
        saveConfig();
        renderGenderAndBubbleSettings();
        renderSnackBar();
        checkPupAchievements();
        if (config.puppyEnabled) {
          setPuppyState('love_firework', 110);
          showPuppyBubble(getPersExtra('genderSwitch', { nextTxt }), 2800);
        }
      });
      boxEl.appendChild(b);
    }
  };
  const pupBubModeBtn = root.querySelector('#st-tb-pup-bub-mode');
  if (pupBubModeBtn) {
    pupBubModeBtn.addEventListener('click', () => {
      config.puppyBubbleMode = (config.puppyBubbleMode || 'wrap') === 'wrap' ? 'split' : 'wrap';
      saveConfig();
      renderGenderAndBubbleSettings();
      if (config.puppyEnabled) {
        showPuppyBubble(getPersExtra(config.puppyBubbleMode === 'split' ? 'bubModeSplit' : 'bubModeWrap'), 2800);
      }
    });
  }
  renderGenderAndBubbleSettings();
  const lookTabBtnForGender = root.querySelector('[data-px-tab="look"]');
  if (lookTabBtnForGender) lookTabBtnForGender.addEventListener('click', renderGenderAndBubbleSettings);

  if (wishBonusBtn) {
    wishBonusBtn.addEventListener('click', () => {
      const wl = ensureDailyWishlist();
      if (wl.allClaimed || !wl.items.every(w => w.claimed)) return;
      wl.allClaimed = true;
      config.puppyCoins = Math.max(0, Math.floor(config.puppyCoins || 0)) + 5;
      config.puppyStats.coinsEarned = (config.puppyStats.coinsEarned || 0) + 5;
      addPupAffinity(3, 'wish_bonus');
      saveConfig();
      updatePupStatBars();
      checkPupAchievements();
      renderWishlist();
      if (config.puppyEnabled) {
        setPuppyState('love_firework', 120);
        showPuppyBubble(pickPersLine(WISH_THANK_BY_PERS) + ' (全达成 +5币)', 3000);
      }
    });
  }

