  let toyCanvas = null;
  let toyCtx = null;
  let toyRaf = 0;
  let toyActive = null;
  let lastInteractBubbleAt = 0;

  const ensureToyDaily = () => {
    const today = new Date().toISOString().slice(0, 10);
    if (!config.puppyToyDaily || config.puppyToyDaily.date !== today) {
      config.puppyToyDaily = { date: today, count: 0 };
    }
    return config.puppyToyDaily;
  };

  const recordToyRally = () => {
    config.puppyToyStats = config.puppyToyStats || { plays: 0, used: {}, rallies: 0 };
    config.puppyToyStats.rallies = (config.puppyToyStats.rallies || 0) + 1;
    scheduleSaveConfig();
    checkPupAchievements();
    const now = Date.now();
    if (now - lastInteractBubbleAt > 2600 && config.puppyEnabled) {
      lastInteractBubbleAt = now;
      showPuppyBubble(pickPersLine(TOY_INTERACT_BY_PERS), 1800, true);
    }
  };

  const onToyPointerMove = (e) => {
    if (!toyActive) return;
    toyActive.pointerX = e.clientX;
    toyActive.pointerY = e.clientY;
    toyActive.pointerMovedAt = Date.now();
  };

  const onToyPointerDown = (e) => {
    if (!toyActive) return;
    if (e.target && e.target.closest && e.target.closest('button, input, textarea, select, a, #st-tb-puppy-bag, #st-tb-panel')) return;
    const cx = e.clientX;
    const cy = e.clientY;
    const t = Date.now();
    toyActive.pointerX = cx;
    toyActive.pointerY = cy;
    toyActive.pointerMovedAt = t;
    toyActive.expiresAt = Math.max(toyActive.expiresAt, t + 6500);

    if (toyActive.kind === 'tennis') {
      const b = toyActive;
      const dx = (pup.x + 36) - cx;
      b.x = cx;
      b.y = Math.min(cy, b.floorY - 24);
      b.vx = clamp(dx * 0.045, -7.5, 7.5) || ((Math.random() < 0.5 ? -1 : 1) * 5.2);
      b.vy = -(6.2 + Math.random() * 2.5);
      b.userRipples.push({ x: cx, y: cy, r: 6, life: 14 });
      recordToyRally();
    } else if (toyActive.kind === 'frisbee') {
      const fr = toyActive;
      fr.phase = 'fly';
      fr.caughtUntil = 0;
      const dx = (pup.x + 36) - cx;
      fr.x = cx;
      fr.y = Math.min(cy, fr.floorY - 46);
      fr.vx = clamp(dx * 0.048, -7.2, 7.2) || ((Math.random() < 0.5 ? -1 : 1) * 5.6);
      fr.vy = -2.2;
      fr.trail = [];
      fr.userRipples.push({ x: cx, y: cy, r: 6, life: 14 });
      recordToyRally();
    } else if (toyActive.kind === 'bubbles') {
      const bm = toyActive;
      let popped = false;
      for (let i = bm.bubbles.length - 1; i >= 0; i--) {
        const bb = bm.bubbles[i];
        if (Math.hypot(bb.x - cx, bb.y - cy) < bb.r + 18) {
          bm.pops.push({ x: bb.x, y: bb.y, r: bb.r, life: 12 });
          bm.bubbles.splice(i, 1);
          bm.hits += 1;
          popped = true;
          break;
        }
      }
      if (!popped) {
        for (let k = 0; k < 4; k++) {
          bm.bubbles.push({
            x: cx + (Math.random() - 0.5) * 26,
            y: cy + (Math.random() - 0.5) * 18,
            r: 10 + Math.random() * 9,
            vx: (Math.random() - 0.5) * 1.4,
            vy: -(0.4 + Math.random() * 0.6),
            hue: Math.floor(Math.random() * 360),
            phase: Math.random() * Math.PI * 2,
          });
        }
      }
      recordToyRally();
    } else if (toyActive.kind === 'laser') {
      const ls = toyActive;
      ls.tx = cx;
      ls.ty = cy;
      ls.x = cx;
      ls.y = cy;
      ls.userRipples.push({ x: cx, y: cy, r: 5, life: 12 });
      recordToyRally();
    }
  };

  const ensureToyCanvas = () => {
    if (toyCanvas && doc.body.contains(toyCanvas)) return toyCanvas;
    toyCanvas = doc.createElement('canvas');
    toyCanvas.id = 'st-tb-toy-layer';
    toyCanvas.style.cssText = 'position:fixed;inset:0;width:100vw;height:100vh;pointer-events:none;z-index:2147483640;';
    toyCanvas.width = win.innerWidth;
    toyCanvas.height = win.innerHeight;
    doc.body.appendChild(toyCanvas);
    toyCtx = toyCanvas.getContext('2d');
    return toyCanvas;
  };

  const stopDesktopToys = (enterPant = false) => {
    if (toyRaf) { cancelAnimationFrame(toyRaf); toyRaf = 0; }
    doc.removeEventListener('pointermove', onToyPointerMove);
    doc.removeEventListener('pointerdown', onToyPointerDown);
    const hadToy = Boolean(toyActive);
    toyActive = null;
    if (toyCanvas) {
      toyCanvas.remove();
      toyCanvas = null;
      toyCtx = null;
    }
    if (hadToy && config.puppyEnabled) {
      const maxY = Math.max(12, win.innerHeight - 74);
      pup.y = clamp(pup.homeY ?? defaultPupY(), 12, maxY);
      if (enterPant) {
        setPuppyState('pant', 150);
        showPuppyBubble(pickPersLine(TOY_PANT_BY_PERS), 2600);
      } else if (pup.state === 'toy_chase' || pup.state === 'toy_jump' || pup.state === 'toy_catch') {
        setPuppyState('idle', 100);
      }
      drawPuppyScene();
    }
  };

  const renderToyPanel = () => {
    const stEl = root.querySelector('#st-px-toy-stat');
    const td = ensureToyDaily();
    if (stEl) stEl.textContent = `今日好感 ${Math.min(3, td.count || 0)}/3 · 累计 ${config.puppyToyStats?.plays || 0} 次`;
  };

  const launchDesktopToy = (kind) => {
    if (!config.puppyEnabled) {
      config.puppyEnabled = true;
      saveConfig();
      syncUI();
      startPuppy();
    }
    stopDesktopToys(false);
    ensureToyCanvas();
    const W = win.innerWidth;
    const H = win.innerHeight;
    toyCanvas.width = W;
    toyCanvas.height = H;
    const now = Date.now();
    config.puppyToyStats = config.puppyToyStats || { plays: 0, used: {}, rallies: 0 };
    config.puppyToyStats.plays = (config.puppyToyStats.plays || 0) + 1;
    config.puppyToyStats.used = config.puppyToyStats.used || {};
    config.puppyToyStats.used[kind] = true;
    adjustPupStats(-1, -1, 10);

    const td = ensureToyDaily();
    let affNote = '';
    if ((td.count || 0) < 3) {
      td.count = (td.count || 0) + 1;
      addPupAffinity(2, 'toy');
      affNote = ` (好感+2, 今日 ${td.count}/3)`;
    }
    if (typeof progressPupWish === 'function') progressPupWish('toy', 1);
    saveConfig();
    updatePupStatBars();
    checkPupAchievements();
    renderToyPanel();

    const floorY = Math.max(80, Math.min(H - 26, (pup.homeY ?? defaultPupY()) + 58));
    if (kind === 'tennis') {
      const fromLeft = pup.x > W * 0.5;
      toyActive = {
        kind: 'tennis',
        startedAt: now,
        expiresAt: now + 13500,
        hits: 0,
        x: fromLeft ? 48 : W - 48,
        y: Math.max(60, floorY - 180),
        vx: (fromLeft ? 1 : -1) * (5.2 + Math.random() * 2.5),
        vy: -4.2,
        rot: 0,
        userRipples: [],
        pointerX: 0,
        pointerY: 0,
        pointerMovedAt: 0,
        floorY,
      };
    } else if (kind === 'frisbee') {
      const fromLeft = pup.x > W * 0.5;
      toyActive = {
        kind: 'frisbee',
        phase: 'fly',
        startedAt: now,
        expiresAt: now + 13500,
        hits: 0,
        x: fromLeft ? 40 : W - 40,
        y: Math.max(70, floorY - 135),
        vx: (fromLeft ? 1 : -1) * 5.6,
        vy: -1.6,
        spin: 0,
        caughtUntil: 0,
        trail: [],
        userRipples: [],
        pointerX: 0,
        pointerY: 0,
        pointerMovedAt: 0,
        floorY,
      };
    } else if (kind === 'bubbles') {
      const bubbles = [];
      for (let i = 0; i < 12; i++) {
        bubbles.push({
          x: 60 + Math.random() * Math.max(120, W - 120),
          y: Math.max(55, floorY - 48 - Math.random() * 210),
          r: 10 + Math.random() * 9,
          vx: (Math.random() - 0.5) * 0.65,
          vy: -(0.18 + Math.random() * 0.28),
          hue: Math.floor(Math.random() * 360),
          phase: Math.random() * Math.PI * 2,
        });
      }
      toyActive = {
        kind: 'bubbles',
        startedAt: now,
        expiresAt: now + 22000,
        hits: 0,
        bubbles,
        pops: [],
        pointerX: 0,
        pointerY: 0,
        pointerMovedAt: 0,
        floorY,
      };
    } else if (kind === 'laser') {
      toyActive = {
        kind: 'laser',
        startedAt: now,
        expiresAt: now + 14000,
        hits: 0,
        x: clamp(pup.x + 160, 50, W - 50),
        y: floorY - 24,
        tx: clamp(pup.x - 160, 50, W - 50),
        ty: floorY - 24,
        nextDartAt: now + 700,
        pointerX: 0,
        pointerY: 0,
        pointerMovedAt: 0,
        trail: [],
        userRipples: [],
        floorY,
      };
    }

    doc.addEventListener('pointermove', onToyPointerMove);
    doc.addEventListener('pointerdown', onToyPointerDown);
    const startBank = TOY_START_BY_PERS[getCurPersKey()] || TOY_START_BY_PERS.sleepyhead;
    showPuppyBubble(formatPupText(pick(startBank[kind] || startBank.tennis)) + affNote, 2400);

    let pupVx = 0;
    let jumpVy = 0;
    let lastFrameAt = performance.now();
    const basePupY = clamp(pup.homeY ?? defaultPupY(), 12, Math.max(12, H - 74));
    pup.y = basePupY;

    const drawRipples = (arr) => {
      if (!arr) return;
      for (let i = arr.length - 1; i >= 0; i--) {
        const rp = arr[i];
        rp.life -= 1;
        rp.r += 2.2;
        toyCtx.strokeStyle = `rgba(255,158,181,${rp.life / 14})`;
        toyCtx.lineWidth = 2;
        toyCtx.beginPath(); toyCtx.arc(rp.x, rp.y, rp.r, 0, Math.PI * 2); toyCtx.stroke();
        if (rp.life <= 0) arr.splice(i, 1);
      }
    };

    const stepToy = (nowPerf) => {
      if (!toyActive || !toyCanvas || !toyCtx) return;
      const dt = Math.min(2.2, Math.max(0.4, (nowPerf - lastFrameAt) / 16.67));
      lastFrameAt = nowPerf;
      const t = Date.now();
      const CW = win.innerWidth;
      const CH = win.innerHeight;
      if (toyCanvas.width !== CW || toyCanvas.height !== CH) {
        toyCanvas.width = CW;
        toyCanvas.height = CH;
      }
      toyCtx.clearRect(0, 0, CW, CH);
      const maxX = Math.max(16, CW - 82);
      const pupCx = pup.x + 36;
      const pupCy = pup.y + 36;

      // 丝滑抛物线重力落回地面（绝不瞬移或抽搐）
      if (pup.y < basePupY || jumpVy < 0) {
        pup.y += jumpVy * dt;
        jumpVy += 0.48 * dt;
        if (pup.y >= basePupY) {
          pup.y = basePupY;
          jumpVy = 0;
        }
      }

      if (toyActive.kind === 'tennis') {
        const b = toyActive;
        b.vy += 0.32 * dt;
        b.x += b.vx * dt;
        b.y += b.vy * dt;
        b.rot += b.vx * 0.08 * dt;
        if (b.x < 18) { b.x = 18; b.vx = Math.abs(b.vx) * 0.88; }
        if (b.x > CW - 18) { b.x = CW - 18; b.vx = -Math.abs(b.vx) * 0.88; }
        if (b.y > b.floorY - 12) {
          b.y = b.floorY - 12;
          b.vy = -Math.abs(b.vy) * 0.76;
          b.vx *= Math.pow(0.96, dt);
        }
        const dx = b.x - pupCx;
        const targetVx = Math.abs(dx) > 6 ? clamp(dx * 0.14, -5.4, 5.4) : 0;
        pupVx += (targetVx - pupVx) * Math.min(1, 0.24 * dt);
        pup.x = clamp(pup.x + pupVx * dt, 12, maxX);
        if (Math.abs(pupVx) > 0.35) pup.dir = pupVx >= 0 ? 1 : -1;
        pup.state = pup.y < basePupY - 3 ? 'toy_jump' : 'toy_chase';

        if (Math.hypot(b.x - pupCx, b.y - pupCy) < 42 && b.vy > -1) {
          b.vy = -(8.4 + Math.random() * 2.6);
          if (b.pointerX > 0 && t - b.pointerMovedAt < 4000) {
            b.vx = clamp((b.pointerX - pupCx) * 0.032, -6.8, 6.8);
          } else {
            b.vx = (pupCx < CW * 0.5 ? 1 : -1) * (4.2 + Math.random() * 2.5);
          }
          b.hits += 1;
          if (pup.y >= basePupY - 2) jumpVy = -7.2;
          pup.state = 'toy_jump';
          spawnPupFx('sparkle', 12, 6);
          if (b.hits >= 8) {
            stopDesktopToys(true);
            return;
          }
        }
        drawRipples(b.userRipples);
        toyCtx.save();
        toyCtx.translate(b.x, b.y);
        toyCtx.rotate(b.rot);
        toyCtx.fillStyle = '#c8f042';
        toyCtx.strokeStyle = '#3b2a22';
        toyCtx.lineWidth = 2;
        toyCtx.beginPath(); toyCtx.arc(0, 0, 11, 0, Math.PI * 2); toyCtx.fill(); toyCtx.stroke();
        toyCtx.strokeStyle = '#ffffff';
        toyCtx.lineWidth = 1.6;
        toyCtx.beginPath(); toyCtx.arc(-6, 0, 7, -0.9, 0.9); toyCtx.stroke();
        toyCtx.beginPath(); toyCtx.arc(6, 0, 7, Math.PI - 0.9, Math.PI + 0.9); toyCtx.stroke();
        toyCtx.restore();
      } else if (toyActive.kind === 'frisbee') {
        const fr = toyActive;
        if (fr.phase === 'caught') {
          // 叼住飞盘：丝滑贴合到嘴边 + 优雅落地后带盘小跑，绝不僵硬瞬移
          const mouthX = pupCx + pup.dir * 20;
          const mouthY = pupCy - 5;
          fr.x += (mouthX - fr.x) * Math.min(1, 0.35 * dt);
          fr.y += (mouthY - fr.y) * Math.min(1, 0.35 * dt);
          fr.spin += 0.06 * dt;
          pupVx *= Math.pow(0.88, dt);
          pup.x = clamp(pup.x + pupVx * dt, 12, maxX);
          pup.state = pup.y < basePupY - 3 ? 'toy_jump' : 'toy_catch';
          if (t >= fr.caughtUntil && pup.y >= basePupY - 1) {
            if (fr.hits >= 5) {
              stopDesktopToys(true);
              return;
            }
            // 从嘴边丝滑甩飞出去（绝不凭空瞬移高度）
            fr.phase = 'fly';
            const launchDir = pupCx < CW * 0.5 ? 1 : -1;
            pup.dir = launchDir;
            fr.vx = launchDir * (5.6 + Math.random() * 1.8);
            fr.vy = -5.4;
            fr.trail = [];
          }
        } else {
          fr.vy += 0.055 * dt;
          fr.x += fr.vx * dt;
          fr.y += fr.vy * dt;
          fr.spin += 0.28 * dt;
          fr.trail.push({ x: fr.x, y: fr.y });
          if (fr.trail.length > 10) fr.trail.shift();
          if (fr.x < 26) { fr.x = 26; fr.vx = Math.abs(fr.vx) * 0.92; }
          if (fr.x > CW - 26) { fr.x = CW - 26; fr.vx = -Math.abs(fr.vx) * 0.92; }
          if (fr.y > fr.floorY - 12) { fr.y = fr.floorY - 12; fr.vy = -3.8; }

          // 预判飞盘落点丝滑加速追击
          const leadX = clamp(fr.x + fr.vx * 6, 24, CW - 24);
          const dx = leadX - pupCx;
          const targetVx = Math.abs(dx) > 5 ? clamp(dx * 0.16, -6.2, 6.2) : 0;
          pupVx += (targetVx - pupVx) * Math.min(1, 0.22 * dt);
          pup.x = clamp(pup.x + pupVx * dt, 12, maxX);
          if (Math.abs(pupVx) > 0.35) pup.dir = pupVx >= 0 ? 1 : -1;
          pup.state = pup.y < basePupY - 3 ? 'toy_jump' : 'toy_chase';

          // 接近时丝滑起跳接盘
          const distNow = Math.hypot(fr.x - pupCx, fr.y - pupCy);
          if (Math.abs(fr.x - pupCx) < 75 && fr.y < pupCy - 14 && fr.y > pupCy - 130 && pup.y >= basePupY - 2) {
            jumpVy = -Math.min(10.8, Math.max(7.2, Math.sqrt(Math.max(10, pupCy - fr.y) * 1.05)));
            pup.state = 'toy_jump';
          }
          if (distNow < 42 && fr.vy > -3.5) {
            fr.phase = 'caught';
            fr.hits += 1;
            fr.caughtUntil = t + 850;
            fr.trail = [];
            spawnPupFx('star', 12, 5);
            showPuppyBubble(pickPersLine(TOY_INTERACT_BY_PERS), 1500, true);
          }
        }
        drawRipples(fr.userRipples);
        // 丝滑飞行拖尾
        if (fr.trail && fr.trail.length > 1) {
          for (let i = 0; i < fr.trail.length; i++) {
            const pt = fr.trail[i];
            const al = ((i + 1) / fr.trail.length) * 0.28;
            toyCtx.fillStyle = `rgba(255,140,170,${al})`;
            toyCtx.beginPath(); toyCtx.ellipse(pt.x, pt.y, 11 * ((i + 1) / fr.trail.length), 3.2, 0, 0, Math.PI * 2); toyCtx.fill();
          }
        }
        toyCtx.save();
        toyCtx.translate(fr.x, fr.y);
        const tilt = fr.phase === 'caught' ? 0 : clamp(fr.vy * 0.04, -0.22, 0.22);
        toyCtx.rotate(tilt);
        toyCtx.fillStyle = '#ff6b8b';
        toyCtx.strokeStyle = '#3b2a22';
        toyCtx.lineWidth = 2;
        toyCtx.beginPath(); toyCtx.ellipse(0, 0, 18, 6.5, 0, 0, Math.PI * 2); toyCtx.fill(); toyCtx.stroke();
        toyCtx.fillStyle = '#ffd1dc';
        toyCtx.beginPath(); toyCtx.ellipse(Math.cos(fr.spin) * 4, -1.5, 9, 2.8, 0, 0, Math.PI * 2); toyCtx.fill();
        toyCtx.restore();
      } else if (toyActive.kind === 'bubbles') {
        const bm = toyActive;
        if (bm.bubbles.length < 10 && bm.hits < 30 && Math.random() < 0.045 * dt) {
          bm.bubbles.push({
            x: 50 + Math.random() * Math.max(120, CW - 100),
            y: bm.floorY - 20,
            r: 10 + Math.random() * 8,
            vx: (Math.random() - 0.5) * 0.65,
            vy: -(0.18 + Math.random() * 0.28),
            hue: Math.floor(Math.random() * 360),
            phase: Math.random() * Math.PI * 2,
          });
        }
        let targetB = null;
        let bestD = 99999;
        bm.bubbles.forEach(bb => {
          bb.phase += 0.038 * dt;
          bb.x += (bb.vx + Math.sin(bb.phase) * 0.32) * dt;
          bb.y += bb.vy * dt;
          if (bb.y < 36) bb.y = bm.floorY - 18;
          if (bb.x < 24) bb.x = CW - 24;
          if (bb.x > CW - 24) bb.x = 24;
          const d = Math.hypot(bb.x - pupCx, bb.y - pupCy);
          if (d < bestD) { bestD = d; targetB = bb; }
        });
        if (targetB) {
          const dx = targetB.x - pupCx;
          const targetVx = Math.abs(dx) > 8 ? clamp(dx * 0.095, -3.2, 3.2) : 0;
          pupVx += (targetVx - pupVx) * Math.min(1, 0.16 * dt);
          pup.x = clamp(pup.x + pupVx * dt, 12, maxX);
          if (Math.abs(pupVx) > 0.25) pup.dir = pupVx >= 0 ? 1 : -1;
          pup.state = pup.y < basePupY - 3 ? 'toy_jump' : 'toy_chase';
          if (Math.abs(dx) < 38 && targetB.y < pupCy - 12 && targetB.y > pupCy - 135 && pup.y >= basePupY - 2) {
            jumpVy = -8.6;
            pup.state = 'toy_jump';
          }
        }
        for (let i = bm.bubbles.length - 1; i >= 0; i--) {
          const bb = bm.bubbles[i];
          if (Math.hypot(bb.x - pupCx, bb.y - pupCy) < bb.r + 24) {
            bm.pops.push({ x: bb.x, y: bb.y, r: bb.r, life: 14 });
            bm.bubbles.splice(i, 1);
            bm.hits += 1;
            if (bm.hits >= 25 && !config.puppyStats?.bubbleManiac) {
              config.puppyStats = config.puppyStats || {};
              config.puppyStats.bubbleManiac = true;
              scheduleSaveConfig();
              checkPupAchievements();
            }
            if (bm.hits >= 30) {
              stopDesktopToys(true);
              return;
            }
          }
        }
        bm.bubbles.forEach(bb => {
          const gr = toyCtx.createRadialGradient(bb.x - bb.r * 0.3, bb.y - bb.r * 0.3, 1, bb.x, bb.y, bb.r);
          gr.addColorStop(0, 'rgba(255,255,255,0.85)');
          gr.addColorStop(0.7, `hsla(${bb.hue}, 85%, 78%, 0.35)`);
          gr.addColorStop(1, `hsla(${(bb.hue + 60) % 360}, 90%, 72%, 0.72)`);
          toyCtx.fillStyle = gr;
          toyCtx.beginPath(); toyCtx.arc(bb.x, bb.y, bb.r, 0, Math.PI * 2); toyCtx.fill();
          toyCtx.fillStyle = 'rgba(255,255,255,0.9)';
          toyCtx.beginPath(); toyCtx.arc(bb.x - bb.r * 0.32, bb.y - bb.r * 0.32, bb.r * 0.22, 0, Math.PI * 2); toyCtx.fill();
        });
        for (let i = bm.pops.length - 1; i >= 0; i--) {
          const pp = bm.pops[i];
          pp.life -= 1;
          toyCtx.strokeStyle = `rgba(180,225,255,${pp.life / 12})`;
          toyCtx.lineWidth = 2;
          toyCtx.beginPath(); toyCtx.arc(pp.x, pp.y, pp.r + (12 - pp.life) * 1.4, 0, Math.PI * 2); toyCtx.stroke();
          if (pp.life <= 0) bm.pops.splice(i, 1);
        }
      } else if (toyActive.kind === 'laser') {
        const ls = toyActive;
        if (t - ls.pointerMovedAt < 2200 && ls.pointerX > 0) {
          ls.tx = clamp(ls.pointerX, 24, CW - 24);
          ls.ty = clamp(ls.pointerY, 40, CH - 24);
        } else if (t >= ls.nextDartAt || Math.hypot(ls.tx - ls.x, ls.ty - ls.y) < 12) {
          ls.tx = 40 + Math.random() * Math.max(120, CW - 80);
          ls.ty = ls.floorY - 12 - Math.random() * 50;
          ls.nextDartAt = t + 650 + Math.random() * 750;
        }
        ls.x += (ls.tx - ls.x) * Math.min(1, 0.18 * dt);
        ls.y += (ls.ty - ls.y) * Math.min(1, 0.18 * dt);
        ls.trail.push({ x: ls.x, y: ls.y });
        if (ls.trail.length > 8) ls.trail.shift();
        const dx = ls.x - pupCx;
        const targetVx = Math.abs(dx) > 8 ? clamp(dx * 0.18, -6.2, 6.2) : 0;
        pupVx += (targetVx - pupVx) * Math.min(1, 0.25 * dt);
        pup.x = clamp(pup.x + pupVx * dt, 12, maxX);
        if (Math.abs(pupVx) > 0.35) pup.dir = pupVx >= 0 ? 1 : -1;
        pup.state = pup.y < basePupY - 3 ? 'toy_jump' : 'toy_chase';
        if (Math.abs(dx) <= 18 && ls.y < pupCy - 20 && pup.y >= basePupY - 2) {
          jumpVy = -8.2;
          pup.state = 'toy_jump';
        }
        drawRipples(ls.userRipples);
        ls.trail.forEach((pt, idx) => {
          toyCtx.fillStyle = `rgba(255,50,70,${(idx + 1) / (ls.trail.length * 2.5)})`;
          toyCtx.beginPath(); toyCtx.arc(pt.x, pt.y, 4, 0, Math.PI * 2); toyCtx.fill();
        });
        const lg = toyCtx.createRadialGradient(ls.x, ls.y, 1, ls.x, ls.y, 13);
        lg.addColorStop(0, '#ffffff');
        lg.addColorStop(0.35, '#ff2a44');
        lg.addColorStop(1, 'rgba(255,42,68,0)');
        toyCtx.fillStyle = lg;
        toyCtx.beginPath(); toyCtx.arc(ls.x, ls.y, 13, 0, Math.PI * 2); toyCtx.fill();
      }

      pup.tick += 1;
      drawPuppyScene();

      if (t >= toyActive.expiresAt) {
        stopDesktopToys(true);
        return;
      }
      toyRaf = requestAnimationFrame(stepToy);
    };
    toyRaf = requestAnimationFrame(stepToy);
  };

  root.querySelectorAll('[data-desk-toy]').forEach(btn => {
    btn.addEventListener('click', () => launchDesktopToy(btn.dataset.deskToy));
  });
  const toyClearBtn = root.querySelector('#st-px-toy-clear');
  if (toyClearBtn) toyClearBtn.addEventListener('click', () => stopDesktopToys(false));

